import {
  Alert,
  AlertTitle,
  Container,
  Divider,
  RadioGroup,
  Skeleton,
  Stack,
  Typography,
} from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useBreakpoints, useWidth } from "../../configs/breakpoints";
import { eDom, eList } from "../../models/core/my-js";
import { useTranslation } from "../../configs/translation";
import { useMyCart } from "../../models/MyCart";
import { useNavigate } from "react-router-dom";
import AppPriceText from "../../layouts/AppPriceText";
import { useLayoutEffect } from "react";
import { useMyClient } from "../../models/MyClient";
import {
  LocalShippingTwoTone,
  PaymentsTwoTone,
  ReceiptLongTwoTone,
  ShoppingCartTwoTone,
} from "@mui/icons-material";
import AppProductCardGrid from "../../layouts/AppProductCardGrid";
import AppAddressWideCard from "../../layouts/AppAddressWideCard";
import { useMyHomeDeps } from "../../models/MyHomeDeps";
import MyRadioWideCard from "../../components/MyRadioWideCard";
import { LoadingButton } from "@mui/lab";

const CheckoutPage = () => {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { forDevice } = useWidth();
  const { down } = useBreakpoints();
  const mobile = down("tablet");
  const {
    isClient,
    addresses,
    addressesWaiting,
    checkoutCall,
    checkoutWaiting,
  } = useMyClient();
  const homeDeps = useMyHomeDeps();
  const { cart, cartProducts, cartValue, cartReset } = useMyCart();
  const cartEmpty = Object.keys(cart).length === 0;
  const subTotal = cartValue();
  const total = subTotal;

  // out if cart empty
  useLayoutEffect(() => {
    if (cartEmpty || !isClient) {
      navigate(window.history.length > 1 ? -1 : "/", { replace: true });
    }
    // eslint-disable-next-line
  }, [cartEmpty, isClient]);

  const totals = (
    <Stack direction="column" spacing={1} width="100%" py={1}>
      <Stack direction="column" spacing={0.5}>
        {total !== subTotal && (
          <>
            <Stack direction="row" width="100%" justifyContent="space-between">
              <Typography children={t("subtotal")} />
              <AppPriceText
                color="secondary"
                price={subTotal}
                currency={t("currency")}
              />
            </Stack>
            <Divider />
          </>
        )}
        <Stack direction="row" width="100%" justifyContent="space-between">
          <Typography children={t("total")} sx={{ fontWeight: "bold" }} />
          <AppPriceText
            color="secondary"
            price={total}
            currency={t("currency")}
          />
        </Stack>
      </Stack>
      <LoadingButton
        loading={checkoutWaiting}
        variant="contained"
        color="secondary"
        type="submit"
        startIcon={<ReceiptLongTwoTone />}
      >
        {t("complete_order")}
      </LoadingButton>
    </Stack>
  );

  return (
    <form
      onSubmit={eDom.eventPreventDefault((event, target) => {
        let fd = new FormData(target);
        checkoutCall(fd.get("payment_method_id"), fd.get("address_id"), () => {
          navigate("/orders", { replace: true });
          cartReset();
        });
      })}
    >
      <AppScaffold
        main={false}
        header={t("complete_order")}
        mobileFooter={totals}
        mobileFooterHeight={150}
      >
        <Container
          fixed={!mobile}
          maxWidth={mobile ? "desktop" : "laptop"}
          sx={{ my: forDevice(2, null, 4) }}
        >
          {!mobile && (
            <Divider
              textAlign="center"
              sx={{ overflow: "auto", width: "100%", mb: 2 }}
            >
              <Typography
                variant="h6"
                color="primary"
                children={t("checkout")}
              />
            </Divider>
          )}

          <Stack direction="column" spacing={3}>
            <Alert severity="info" color="warning">
              <AlertTitle>{t("shipping_not_included")}</AlertTitle>
            </Alert>

            <Stack direction="column" spacing={1}>
              <DividerTitle
                title={t("payment_method")}
                icon={<PaymentsTwoTone />}
              />
              <RadioGroup
                component={Stack}
                spacing={1}
                name="payment_method_id"
              >
                {eList.toArray(homeDeps.data?.payments, (index, item) => (
                  <MyRadioWideCard
                    key={`cpl-${index}`}
                    value={item.id}
                    title={t(item.id)}
                    checked={index === "0"}
                  />
                ))}
              </RadioGroup>
            </Stack>
            <Stack direction="column" spacing={1}>
              <DividerTitle
                title={t("address")}
                icon={<LocalShippingTwoTone />}
              />
              {addressesWaiting && (
                <Skeleton variant="rectangular" width="100%" height={125} />
              )}
              {!addressesWaiting && (
                <RadioGroup component={Stack} spacing={1} name="address_id">
                  {eList.toArray(addresses, (index, item) => (
                    <AppAddressWideCard
                      key={`cal-${index}`}
                      addressId={item.id}
                      address={item}
                      radio={true}
                      checked={index === "0"}
                    />
                  ))}
                </RadioGroup>
              )}
            </Stack>
            <Stack direction="column" spacing={1}>
              <DividerTitle title={t("cart")} icon={<ShoppingCartTwoTone />} />
              <AppProductCardGrid products={cartProducts} inCheckout={true} />
            </Stack>
            {!mobile && (
              <Stack direction="column" spacing={1}>
                <Divider />
                {totals}
              </Stack>
            )}
          </Stack>
        </Container>
      </AppScaffold>
    </form>
  );
};
export default CheckoutPage;

const DividerTitle = ({ title, icon }) => {
  return (
    <Divider
      textAlign="left"
      sx={{
        overflow: "auto",
        width: "100%",
        mb: 2,
      }}
    >
      <Stack
        direction="row"
        width="max-content"
        spacing={1}
        alignItems="center"
      >
        {icon}
        <Typography
          color="primary"
          children={title}
          sx={{
            fontWeight: "bold",
          }}
        />
      </Stack>
    </Divider>
  );
};
