import { FavoriteTwoTone, Favorite, RemoveCircle } from "@mui/icons-material";
import { useMyFav } from "../models/MyFav";
import { useTranslation } from "../configs/translation";
import { LoadingButton } from "@mui/lab";
import MyIcons, { MySubIcon } from "../components/MyIcons";

const AppProductFavBtn = ({
  productId,
  product,
  full = false,
  size = "medium",
  fullWidth = false,
  remover = false,
}) => {
  const { t } = useTranslation();
  const { getFavItem, manageApi } = useMyFav();
  const manage = manageApi(productId, product);

  const item = getFavItem(productId);
  if (remover) {
    return (
      <LoadingButton
        loading={manage.waiting}
        onClick={() => {
          manage.delFavItem();
        }}
        color="error"
        size={size}
        sx={{ px: 1, py: 1 }}
      >
        <MyIcons
          baseIcon={
            <Favorite color={manage.waiting ? "transparent" : "secondary"} />
          }
        >
          <MySubIcon
            icon={
              <RemoveCircle
                color={manage.waiting ? "transparent" : "error2"}
                fontSize={"small"}
              />
            }
            h={4}
            v={4}
          />
        </MyIcons>
      </LoadingButton>
    );
  } else {
    if (full) {
      return (
        <LoadingButton
          loading={manage.waiting}
          loadingPosition={"start"}
          onClick={() => {
            manage.toggleFavItem();
          }}
          variant="text"
          color={item ? "primary4" : "primary"}
          startIcon={
            item ? <Favorite color="secondary" /> : <FavoriteTwoTone />
          }
          size={size}
          fullWidth={fullWidth}
        >
          {item ? t("remove_from_favorites") : t("add_to_favorites")}
        </LoadingButton>
      );
    } else {
      return (
        <LoadingButton
          loading={manage.waiting}
          onClick={() => {
            manage.toggleFavItem();
          }}
          color={item ? "secondary" : "primaryt"}
          size={size}
          sx={{ px: 1, py: 1 }}
        >
          {item ? <Favorite /> : <FavoriteTwoTone />}
        </LoadingButton>
      );
    }
  }
};
export default AppProductFavBtn;
