import {
  Box,
  Card,
  CardActionArea,
  Container,
  Divider,
  Skeleton,
  Stack,
  Typography,
} from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useWidth } from "../../configs/breakpoints";
import { useTranslation } from "../../configs/translation";
import { useMyHome } from "../../models/MyHome";
import { eList } from "../../models/core/my-js";
import { ApisEB } from "../../configs/apis";
import { MyGrid, MyGridItem } from "../../components/MyGrid";
import MyImage from "../../components/MyImage";
import { Link } from "react-router-dom";

const BrandsPage = () => {
  const { forDevice } = useWidth();
  const homeApi = useMyHome();

  return (
    <AppScaffold>
      <Container maxWidth={"desktop"} sx={{ my: forDevice(2, null, 4) }}>
        <BrandsBrands brands={homeApi.data?.brands} />
      </Container>
    </AppScaffold>
  );
};
export default BrandsPage;

const BrandsBrands = ({ brands }) => {
  const { t } = useTranslation();
  const { forDevice } = useWidth();

  if (!brands) {
    return <Skeleton variant="rounded" height={500} />;
  } else if (brands?.length > 0) {
    return (
      <Stack direction="column" spacing={forDevice(2, 4)} width={"100%"}>
        <Divider textAlign="left" sx={{ overflow: "auto", width: "100%" }}>
          <Typography color="primary" children={t("brands")} />
        </Divider>

        <MyGrid
          cols={{ xs: 3, sm: 4, md: 6, lg: 9, xl: 10 }}
          cross={"stretch"}
          mainItem={"stretch"}
          crossItem={"stretch"}
          spacing={1}
          width={"100%"}
        >
          {eList.toArray(brands, (index, brand) => {
            return (
              <MyGridItem key={`mbg-${index}`}>
                <BrandsCard brand={brand} />
              </MyGridItem>
            );
          })}
        </MyGrid>
      </Stack>
    );
  } else {
    return null;
  }
};

const BrandsCard = ({ height, brand }) => {
  const { forLocale } = useTranslation();

  return (
    <Card
      variant={"outlined"}
      sx={{
        position: "relative",
        width: "100%",
        height: "100%",
        bgcolor: "background.white",
        borderColor: "light.main",
      }}
      square
    >
      <CardActionArea
        sx={{
          flexGrow: 1,
          width: "100%",
          height: "100%",
        }}
      >
        <Link
          style={{
            flexGrow: 1,
            width: "100%",
            height: "100%",
            textDecoration: "none",
          }}
          to={`/products/p/1/b/${brand?.id}`}
        >
          <Stack height="100%" direction="column">
            <MyImage
              src={ApisEB.getMedia(brand?.thumbnail)}
              alt={brand?.[forLocale({ ar: "name_alt" }, "name")]}
              height={50}
              width="100%"
              objectFit="contain"
            />
            <Box sx={{ px: 0.25, py: 0.5 }}>
              <Typography
                variant="body2"
                color="primary"
                textAlign={"center"}
                sx={{
                  display: "-webkit-box",
                  overflow: "hidden",
                  WebkitBoxOrient: "vertical",
                  WebkitLineClamp: 2,
                }}
              >
                {brand?.[forLocale({ ar: "name_alt" }, "name")]}
              </Typography>
            </Box>
          </Stack>
        </Link>
      </CardActionArea>
    </Card>
  );
};
