//
import React from "react";
import {
  Typography,
  Box,
  CardActions,
  CardActionArea,
  Card,
  Stack,
  Breadcrumbs,
} from "@mui/material";
import { ApisEB } from "../configs/apis";
import { useTranslation } from "../configs/translation";
import { Link } from "react-router-dom";
import AppProductCartBtn from "./AppProductCartBtn";
import AppProductFavBtn from "./AppProductFavBtn";
import MyFloater from "../components/MyFloater";
import MyImage from "../components/MyImage";
import AppPriceText from "./AppPriceText";
import { useMyCart } from "../models/MyCart";
import { useWidth } from "../configs/breakpoints";
import { cardHeight } from "../configs/params";
//
const AppProductCard = ({
  productId,
  product,
  inFav,
  inCart,
  inCheckout,
  quantity,
}) => {
  const { t, forLocale } = useTranslation();
  const { forDevice } = useWidth();
  const isPriced = product?.price && product?.price > 0;
  const isOutStock = !product?.stock || product?.stock === "0";
  const subtitle = product?.model;
  const { getCartItemValue, getCartItemQty } = useMyCart();
  const itemValue = getCartItemValue(productId);
  const orderQty = quantity && parseInt(quantity) * parseFloat(product?.price);
  const isSubTotal =
    ((inCart || inCheckout) &&
      itemValue &&
      itemValue.toString() !== product?.price) ||
    (orderQty && orderQty.toString() !== product?.price);
  const subTotal = orderQty ?? itemValue;

  const height = cardHeight(forDevice);

  return (
    <Card
      variant={"outlined"}
      sx={{
        position: "relative",
        width: "100%",
        height: height,
        bgcolor: "background.white",
        borderColor: "light.main",
      }}
      square
    >
      <Stack height="100%" direction="column">
        <CardActionArea
          component={Link}
          to={`/product/${productId}`}
          sx={{ flexGrow: 1 }}
        >
          <Stack height="100%" direction="column">
            <MyImage
              src={ApisEB.getMedia(product?.thumbnail)}
              alt={product?.[forLocale({ ar: "name_alt" }, "name")]}
              height={height / 2}
              width="100%"
              objectFit="contain"
            />
            <Box sx={{ px: 0.75, py: 0 }}>
              <Typography
                variant="subtitle2"
                color="primary"
                sx={{
                  fontWeight: "bold",
                  display: "-webkit-box",
                  overflow: "hidden",
                  WebkitBoxOrient: "vertical",
                  WebkitLineClamp: 2,
                }}
              >
                {product?.[forLocale({ ar: "name_alt" }, "name")]}
              </Typography>

              {subtitle && (
                <Typography variant="subtitle2" color="secondary">
                  {subtitle}
                </Typography>
              )}

              {isPriced && (
                <Breadcrumbs
                  separator={
                    <Typography
                      variant={forDevice("caption", "subtitle2")}
                      children={`*${quantity ?? getCartItemQty(productId)}`}
                    />
                  }
                  sx={{
                    "& ol": {
                      alignItems: "baseline",
                    },
                  }}
                >
                  <AppPriceText
                    price={product?.price}
                    priceVariant={forDevice(
                      isSubTotal ? "subtitle1" : "h5",
                      "h5"
                    )}
                    currency={!isSubTotal && t("currency")}
                    currencyVariant="subtitle2"
                    color={"primary"}
                  />
                  {isSubTotal && (
                    <AppPriceText
                      price={subTotal}
                      priceVariant={forDevice("subtitle2", "h5")}
                      currency={t("currency")}
                      currencyVariant={forDevice("caption", "subtitle2")}
                      color={isOutStock ? "primary" : "secondary"}
                    />
                  )}
                </Breadcrumbs>
              )}
            </Box>
          </Stack>
        </CardActionArea>
        {isPriced && (
          <CardActions sx={{ padding: 0.5 }}>
            <AppProductCartBtn
              productId={productId}
              product={product}
              full={false}
              size={"medium"}
              fullWidth={true}
              mobile
            />
          </CardActions>
        )}
      </Stack>

      {isPriced && (
        <MyFloater top={2} start={2}>
          {inFav && !inCheckout && (
            <AppProductFavBtn
              productId={productId}
              product={product}
              full={false}
              size={"small"}
              remover={true}
            />
          )}
          {(inCart || inCheckout) && (
            <AppProductCartBtn
              productId={productId}
              product={product}
              full={false}
              size={"small"}
              remover={true}
            />
          )}
          {!inFav && !inCheckout && (
            <AppProductFavBtn
              productId={productId}
              product={product}
              full={false}
              size={"small"}
            />
          )}
        </MyFloater>
      )}
    </Card>
  );
};
export default AppProductCard;
