import { ApiCall, ApiState } from "./MyApis";
import { eList } from "./core/my-js";
import { AsyncState, Context, CookieState } from "./core/my-react";

export const MyClientContext = Context(() => {
    const client = CookieState('CID');
    const addresses = ApiState("public/ecommerce/clients/addresses/get", {
        autoCall: !!client.value,
        bodyData: {
            CID: client.value
        },
    });

    const loginApi = ApiCall("public/ecommerce/clients/login");
    const registerApi = ApiCall("public/ecommerce/clients/signup");
    const addressApi = ApiCall("public/ecommerce/clients/addresses/add");
    const cartBatchApi = ApiCall("public/ecommerce/clients/cart/batch");
    const favBatchApi = ApiCall("public/ecommerce/clients/wishlist/batch");
    const checkoutApi = ApiCall("public/ecommerce/clients/checkout");
    const orderCancelApi = ApiCall("public/ecommerce/clients/orders/cancel");

    const loginRun = AsyncState(async function ({ username, password, cart, fav }) {
        // login
        let ld = await loginApi({ username, password });
        if (!ld) return null;
        const CID = ld?.CID;
        // cart
        if (cart && cart?.length > 0) {
            let cd = await cartBatchApi({
                CID,
                product_id: eList.toArray(cart, (k, v) => k),
                quantity: eList.toArray(cart, (k, v) => v.qty),
            });
            if (!cd) return null;
        }
        // fav
        if (fav && fav?.length > 0) {
            let fd = await favBatchApi({
                CID,
                product_id: eList.toArray(fav, (k, v) => k),
                wishlist: eList.toArray(fav, (k, v) => 1),
            });
            if (!fd) return null;
        }
        // addresses
        addresses.callApi({ CID: CID });
        // return
        return CID;
    });
    const registerRun = AsyncState(async ({ name, email, telephone, password, city_id, address, cart, fav }) => {
        // register
        name = name.split(" ");
        let rd = await registerApi({
            first_name: name.shift(),
            last_name: name.join(" "),
            email,
            telephone,
            password
        });
        if (!rd) return null;
        const CID = rd?.CID;
        // address
        let ad = await addressApi({
            CID: CID,
            city_id,
            name: "main",
            telephone1: telephone,
            address1: address
        });
        if (!ad) return null;
        // cart
        if (cart && cart?.length > 0) {
            let cd = await cartBatchApi({
                CID,
                product_id: eList.toArray(cart, (k, v) => k),
                quantity: eList.toArray(cart, (k, v) => v.qty),
            });
            if (!cd) return null;
        }
        // fav
        if (fav && fav?.length > 0) {
            let fd = await favBatchApi({
                CID,
                product_id: eList.toArray(fav, (k, v) => k),
                wishlist: eList.toArray(fav, (k, v) => 1),
            });
            if (!fd) return null;
        }
        // addresses
        addresses.callApi({ CID: CID });
        // return
        return CID;
    });
    const checkoutRun = AsyncState(async ({ payment_method_id, address_id }) => {
        // checkout
        let rd = await checkoutApi({
            CID: client.value,
            payment_method_id: payment_method_id,
            pickup: 0,
            address_id: address_id,
            order: 1
        });
        if (!rd) return null;
        return true;
    });
    const orderCancelRun = AsyncState(async ({ order_id }) => {
        // checkout
        let rd = await orderCancelApi({
            CID: client.value,
            order_id: order_id,
        });
        if (!rd) return null;
        return true;
    });

    const loginCall = async (username, password, cart, fav) => {
        client.value = await loginRun.run({ username, password, cart, fav });
    };
    const registerCall = async (name, email, telephone, password, city_id, address, cart, fav) => {
        client.value = await registerRun.run({ name, email, telephone, password, city_id, address, cart, fav });
    }
    const logoutClient = () => {
        client.value = null;
    }
    const checkoutCall = async (payment_method_id, address_id, onSuccess) => {
        let r = await checkoutRun.run({ payment_method_id, address_id });
        if (r && onSuccess) onSuccess();
    }
    const orderCancelCall = async (order_id, onSuccess) => {
        let r = await orderCancelRun.run({ order_id });
        if (r && onSuccess) onSuccess();
    }

    return {
        get CID() { return client.value; },
        get isClient() { return !!client.value; },
        loginCall: loginCall,
        get loginWaiting() { return loginRun.waiting; },
        registerCall: registerCall,
        get registerWaiting() { return registerRun.waiting; },
        logoutClient: logoutClient,
        get addresses() { return addresses.value; },
        get addressesWaiting() { return addresses.waiting; },
        checkoutCall: checkoutCall,
        get checkoutWaiting() { return checkoutRun.waiting; },
        orderCancelCall: orderCancelCall,
        get orderCancelWaiting() { return orderCancelRun.waiting; },
    };
});
export const useMyClient = MyClientContext.Use;
export const MyClientProvider = MyClientContext.Provider;
export const MyClientConsumer = MyClientContext.Consumer;
export const MyClientProvCons = MyClientContext.ProvCons;