import {
  Box,
  Button,
  Container,
  Dialog,
  DialogActions,
  DialogTitle,
  Divider,
  Stack,
  Typography,
  Grid,
} from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useBreakpoints, useWidth } from "../../configs/breakpoints";
import { eList } from "../../models/core/my-js";
import AppProductWideCard from "../../layouts/AppProductWideCard";
import { useTranslation } from "../../configs/translation";
import { useMyCart } from "../../models/MyCart";
import {
  ArrowBackTwoTone,
  ArrowForwardTwoTone,
  CancelTwoTone,
  InfoTwoTone,
  LoginTwoTone,
  ShoppingCartCheckoutTwoTone,
} from "@mui/icons-material";
import { Link, useNavigate } from "react-router-dom";
import AppPriceText from "../../layouts/AppPriceText";
import { State } from "../../models/core/my-react";
import { useMyClient } from "../../models/MyClient";

const CartPage = () => {
  const navigate = useNavigate();
  const { t, forDir } = useTranslation();
  const { forDevice } = useWidth();
  const { down } = useBreakpoints();
  const mobile = down("tablet");
  const { cart, cartValue } = useMyCart();
  const cartEmpty = Object.keys(cart).length === 0;
  const accessDialog = State(false);
  const { isClient } = useMyClient();

  const checkout = !cartEmpty && (
    <Stack direction="column" spacing={1} width="100%" py={1}>
      <Stack direction="row" width="100%" justifyContent="space-between">
        <Typography children={t("subtotal")} />
        <AppPriceText
          color="primary"
          price={cartValue()}
          currency={t("currency")}
        />
      </Stack>
      <Button
        {...(isClient
          ? { component: Link, to: "/checkout" }
          : { onClick: () => (accessDialog.value = true) })}
        variant="contained"
        color="secondary"
        startIcon={<ShoppingCartCheckoutTwoTone />}
      >
        {t("checkout")}
      </Button>
    </Stack>
  );

  return (
    <AppScaffold
      main={false}
      header={t("cart")}
      mobileFooter={checkout}
      mobileFooterHeight={100}
    >
      <Container
        fixed={!mobile}
        maxWidth={mobile ? "desktop" : "laptop"}
        sx={{ my: forDevice(2, null, 4) }}
      >
        {!mobile && (
          <Divider
            textAlign="left"
            sx={{ overflow: "auto", width: "100%", mb: 2 }}
          >
            <Typography color="primary" children={t("cart")} />
          </Divider>
        )}

        {cartEmpty && (
          <Box
            sx={{
              width: "100%",
              py: { mobile: 10, tablet: 30 },
              bgcolor: "background.light",
            }}
          >
            <Stack spacing={forDevice(2, null, 4)} alignItems={"center"}>
              <Typography
                variant="h5"
                textAlign="center"
                children={t("cart_empty")}
              />
              <Button
                variant="text"
                onClick={() => {
                  navigate(window.history.length > 1 ? -1 : "/");
                }}
                color="primary"
                startIcon={forDir(
                  <ArrowBackTwoTone fontSize="small" />,
                  <ArrowForwardTwoTone fontSize="small" />
                )}
              >
                {t("back")}
              </Button>
            </Stack>
          </Box>
        )}

        {!cartEmpty && (
          <>
            <Stack spacing={1}>
              {eList.toArray(cart, (id, item) => (
                <AppProductWideCard
                  key={`cpl-${id}`}
                  productId={id}
                  product={item.product}
                  inCart={true}
                />
              ))}
            </Stack>
            {!mobile && checkout}
          </>
        )}
      </Container>

      <Dialog
        open={accessDialog.value}
        onClose={() => (accessDialog.value = false)}
        fullWidth={true}
        maxWidth={"xs"}
        PaperProps={{ sx: { overflow: "visible", overflowY: "visible" } }}
      >
        <Box
          sx={{ textAlign: "center", mt: -10 }}
          children={
            <Box
              sx={{
                bgcolor: "background.white",
                borderRadius: "100%",
                width: 125,
                height: 125,
                overflow: "hidden",
                mx: "auto",
              }}
              children={
                <InfoTwoTone
                  className="animate-pulsate-fwd"
                  sx={{
                    width: "100%",
                    height: "100%",
                  }}
                  color="secondary"
                />
              }
            />
          }
        />

        <DialogTitle
          children={t("access_for_order")}
          sx={{ textAlign: "center" }}
        />
        <DialogActions>
          <Grid container spacing={1}>
            <Grid item xs={6}>
              <Button
                component={Link}
                to={`/login/cart`}
                variant={"outlined"}
                color="primary"
                startIcon={<LoginTwoTone />}
                children={t("login")}
                fullWidth={true}
                sx={{ px: 0.5 }}
              />
            </Grid>
            <Grid item xs={6}>
              <Button
                onClick={() => (accessDialog.value = false)}
                variant={"outlined"}
                color="error"
                startIcon={<CancelTwoTone />}
                children={t("cancel")}
                fullWidth={true}
                sx={{ px: 0.5 }}
              />
            </Grid>
          </Grid>
        </DialogActions>
      </Dialog>
    </AppScaffold>
  );
};
export default CartPage;
