import {
  Box,
  Button,
  Container,
  Divider,
  Stack,
  Typography,
} from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useBreakpoints, useWidth } from "../../configs/breakpoints";
import { useMyFav } from "../../models/MyFav";
import { eList } from "../../models/core/my-js";
import AppProductWideCard from "../../layouts/AppProductWideCard";
import { useTranslation } from "../../configs/translation";
import { ArrowBackTwoTone, ArrowForwardTwoTone } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

const FavoritesPage = () => {
  const navigate = useNavigate();
  const { t, forDir } = useTranslation();
  const { forDevice } = useWidth();
  const { down } = useBreakpoints();
  const mobile = down("tablet");
  const { fav } = useMyFav();
  const favEmpty = Object.keys(fav).length === 0;

  return (
    <AppScaffold
      fixed={!mobile}
      maxWidth={mobile ? "desktop" : "laptop"}
      main={false}
      header={t("favorites")}
    >
      <Container
        fixed={!mobile}
        maxWidth={mobile ? "desktop" : "laptop"}
        sx={{ my: forDevice(2, null, 4) }}
      >
        {!mobile && (
          <Divider
            textAlign="left"
            sx={{ overflow: "auto", width: "100%", mb: 2 }}
          >
            <Typography color="primary" children={t("favorites")} />
          </Divider>
        )}

        {favEmpty && (
          <Box
            sx={{
              width: "100%",
              py: { mobile: 10, tablet: 30 },
              bgcolor: "background.light",
            }}
          >
            <Stack spacing={forDevice(2, null, 4)} alignItems={"center"}>
              <Typography
                variant="h5"
                textAlign="center"
                children={t("favorites_empty")}
              />
              <Button
                variant="text"
                onClick={() => {
                  navigate(window.history.length > 1 ? -1 : "/");
                }}
                color="primary"
                startIcon={forDir(
                  <ArrowBackTwoTone fontSize="small" />,
                  <ArrowForwardTwoTone fontSize="small" />
                )}
              >
                {t("back")}
              </Button>
            </Stack>
          </Box>
        )}

        {!favEmpty && (
          <Stack spacing={1}>
            {eList.toArray(fav, (id, item) => (
              <AppProductWideCard
                key={`fpl-${id}`}
                productId={id}
                product={item}
                inFav={true}
              />
            ))}
          </Stack>
        )}
      </Container>
    </AppScaffold>
  );
};
export default FavoritesPage;
