import { Box, Divider, Skeleton, Stack, Tab, Tabs } from "@mui/material";
import { useTranslation } from "../../../configs/translation";
import { eList } from "../../../models/core/my-js";
import AppHtmlViewer from "../../../layouts/AppHtmlViewer";
import { TabContext, TabPanel } from "@mui/lab";
import { State } from "../../../models/core/my-react";

const ProductDesc = ({ product }) => {
  const { t, forLocale } = useTranslation();
  const tabPage = State("0");

  const desc = product?.[forLocale({ ar: "description_alt" }, "description")];
  const tech = product?.info_tech;
  const content = product?.info_content;

  if (!product) {
    return (
      <Stack spacing={3} px={1}>
        <Divider />
        <Skeleton variant="rectangular" width="100%" height={300} />
      </Stack>
    );
  } else if (!desc && !tech && !content) {
    return null;
  } else {
    let k = [];
    let v = [];
    if (desc) {
      k.push(t("desc"));
      v.push(desc);
    }
    if (tech) {
      k.push(t("tech_info"));
      v.push(tech);
    }
    if (content) {
      k.push(t("package_contents"));
      v.push(content);
    }

    return (
      <Stack spacing={2} mt={1}>
        <Divider />
        <TabContext value={tabPage.value}>
          <Tabs
            value={tabPage.value}
            onChange={(evt, v) => (tabPage.value = v)}
            centered
            textColor="secondary"
            indicatorColor="secondary"
          >
            {eList.generateArray(k.length, (index) => (
              <Tab
                key={`pdk-${index}`}
                label={k?.[index]}
                value={index.toString()}
                sx={{ fontWeight: "bold" }}
              />
            ))}
          </Tabs>
          <Box sx={{ bgcolor: "background.light" }}>
            {eList.generateArray(v.length, (index) => (
              <TabPanel key={`pdv-${index}`} value={index.toString()}>
                <AppHtmlViewer html={v?.[index]} />
              </TabPanel>
            ))}
          </Box>
        </TabContext>
      </Stack>
    );
  }
};
export default ProductDesc;
