import {
  TextField,
  Card,
  CardContent,
  Container,
  InputAdornment,
  Stack,
  Typography,
  Box,
  Button,
  MenuItem,
} from "@mui/material";
import { useTranslation } from "../../configs/translation";
import AppScaffold from "../../layouts/AppScaffold";
import { useBreakpoints, useWidth } from "../../configs/breakpoints";
import MyImage from "../../components/MyImage";
import LogoIcon from "../../assets/images/logoIcon.png";
import {
  PersonAddAltTwoTone,
  PhoneTwoTone,
  LoginTwoTone,
  PermIdentityTwoTone,
  PinDropTwoTone,
  LocationCityTwoTone,
  EmailTwoTone,
  PasswordTwoTone,
} from "@mui/icons-material";
import { Link, useNavigate, useParams } from "react-router-dom";
import { eDom, eList } from "../../models/core/my-js";
import { useMyClient } from "../../models/MyClient";
import { useLayoutEffect } from "react";
import { LoadingButton } from "@mui/lab";
import { useMyHomeDeps } from "../../models/MyHomeDeps";
import { useMyCart } from "../../models/MyCart";
import { useMyFav } from "../../models/MyFav";

const RegisterPage = () => {
  const { nav } = useParams();
  const { t } = useTranslation();
  const { forDevice } = useWidth();
  const { down } = useBreakpoints();
  const navigate = useNavigate();
  const mobile = down("tablet");
  const { isClient, registerCall, registerWaiting } = useMyClient();
  const { cart } = useMyCart();
  const { fav } = useMyFav();

  // check is client
  useLayoutEffect(() => {
    if (isClient) navigate(`/${nav ? nav : ""}`, { replace: true });
  }, [isClient, navigate, nav]);

  return (
    <AppScaffold main={false} header={t("register")}>
      <Container
        fixed={!mobile}
        maxWidth={mobile ? "desktop" : "tablet"}
        sx={{ my: forDevice(2, null, 4) }}
      >
        <form
          onSubmit={eDom.eventPreventDefault((event, target) => {
            let fd = new FormData(target);
            registerCall(
              fd.get("name"),
              fd.get("email"),
              fd.get("telephone"),
              fd.get("password"),
              fd.get("city_id"),
              fd.get("address"),
              cart,
              fav
            );
          })}
        >
          <MobileRegister mobile={mobile} loading={registerWaiting} />
          <DesktopRegister mobile={mobile} loading={registerWaiting} />
        </form>
      </Container>
    </AppScaffold>
  );
};
export default RegisterPage;

const RegisterRegister = ({ loading }) => {
  const { t, forLocale } = useTranslation();
  const { nav } = useParams();
  const homeDeps = useMyHomeDeps();

  return (
    <>
      <Box sx={{ width: "100%", textAlign: "start" }}>
        <Typography
          variant="h5"
          children={t("welcome_greeting")}
          sx={{ fontWeight: "bold" }}
        />

        {/* <Typography
          variant="h6"
          children={t("register_desc")}
          sx={{ color: "primary4.main" }}
        /> */}
      </Box>

      <TextField
        label={t("name")}
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment
              position="start"
              children={<PermIdentityTwoTone />}
            />
          ),
          sx: { py: 1 },
        }}
        name="name"
        type="text"
        required
        inputProps={{ minLength: 2 }}
      />

      <TextField
        label={t("email")}
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment position="start" children={<EmailTwoTone />} />
          ),
          sx: { py: 1 },
        }}
        name="email"
        type="email"
        required
      />

      <TextField
        label={t("mobile_number")}
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment position="start" children={<PhoneTwoTone />} />
          ),
          sx: { py: 1 },
        }}
        name="telephone"
        type="tel"
        required
        inputProps={{ minLength: 11, maxLength: 11 }}
      />

      <TextField
        label={t("password")}
        size="normal"
        margin="normal"
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment position="start" children={<PasswordTwoTone />} />
          ),
          sx: { py: 1 },
        }}
        name="password"
        type="password"
        required
        inputProps={{ minLength: 6 }}
      />

      <TextField
        label={t("city")}
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment
              position="start"
              children={<LocationCityTwoTone />}
            />
          ),
          sx: { py: 1 },
        }}
        select
        defaultValue=""
        name="city_id"
        required
        children={[
          <MenuItem
            key={`rcs--1`}
            value={""}
            children={<em>{`- ${t("city")} -`}</em>}
          />,
          ...eList.toArray(homeDeps.data?.cities, (index, item) => (
            <MenuItem key={`rcs-${index}`} value={item?.id}>
              {item?.[forLocale({ ar: "name_native" }, "name")]}
            </MenuItem>
          )),
        ]}
        inputProps={{ sx: { py: 0.8 } }}
      />

      <TextField
        label={t("address")}
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment position="start" children={<PinDropTwoTone />} />
          ),
          sx: { py: 1 },
        }}
        name="address"
        type="text"
        required
        inputProps={{ minLength: 2 }}
      />

      <LoadingButton
        loading={loading}
        loadingPosition="start"
        startIcon={<PersonAddAltTwoTone />}
        variant="contained"
        type="submit"
        children={t("register")}
        fullWidth
      />

      <Button
        component={Link}
        to={`/login${nav ? `/${nav}` : ""}`}
        replace={true}
        variant={"outlined"}
        color="primary"
        startIcon={<LoginTwoTone />}
        children={t("login_title")}
      />
    </>
  );
};

const MobileRegister = ({ mobile, loading }) => {
  const { t } = useTranslation();

  if (!mobile) {
    return null;
  } else {
    return (
      <Stack spacing={3} alignItems={"center"}>
        <MyImage
          src={LogoIcon}
          alt={t("welcome_greeting")}
          width={100}
          height={100}
          style={{ borderRadius: 4 }}
        />

        <RegisterRegister loading={loading} />
      </Stack>
    );
  }
};

const DesktopRegister = ({ mobile, loading }) => {
  const { t } = useTranslation();

  if (mobile) {
    return null;
  } else {
    return (
      <Card variant={"outlined"}>
        <CardContent>
          <Stack spacing={3} alignItems={"center"}>
            <Typography variant="h3" children={t("register")} />

            <RegisterRegister loading={loading} />
          </Stack>
        </CardContent>
      </Card>
    );
  }
};
