//
import React from "react";
import {
  Typography,
  CardActionArea,
  Card,
  Stack,
  Grid,
  Breadcrumbs,
} from "@mui/material";
import { ApisEB } from "../configs/apis";
import { useTranslation } from "../configs/translation";
import { Link } from "react-router-dom";
import AppProductCartBtn from "./AppProductCartBtn";
import AppProductFavBtn from "./AppProductFavBtn";
import MyImage from "../components/MyImage";
import { useWidth } from "../configs/breakpoints";
import MyFloater from "../components/MyFloater";
import AppPriceText from "./AppPriceText";
import { useMyCart } from "../models/MyCart";
import { cardWideHeight } from "../configs/params";
//
const AppProductWideCard = ({
  productId,
  product,
  inFav,
  inCart,
  inCheckout,
  quantity,
}) => {
  const { t, forLocale } = useTranslation();
  const { forDevice } = useWidth();
  const isPriced = product?.price && product?.price > 0;
  const subtitle = product?.model;
  const { getCartItemValue, getCartItemQty } = useMyCart();
  const itemValue = getCartItemValue(productId);
  const orderQty = quantity && parseInt(quantity) * parseFloat(product?.price);
  const isSubTotal =
    ((inCart || inCheckout) &&
      itemValue &&
      itemValue.toString() !== product?.price) ||
    (orderQty && orderQty.toString() !== product?.price);
  const subTotal = orderQty ?? itemValue;

  const height = cardWideHeight(forDevice);

  return (
    <Card
      variant={"outlined"}
      sx={{
        position: "relative",
        width: "100%",
        height: height,
        bgcolor: "background.white",
        borderColor: "light.main",
      }}
      square
    >
      <Grid container sx={{ height: "100%", width: "100%" }}>
        <Grid item xs={5} sx={{ height: "100%" }}>
          <CardActionArea
            component={Link}
            to={`/product/${productId}`}
            sx={{ height: "100%", width: "100%" }}
          >
            <MyImage
              src={ApisEB.getMedia(product?.thumbnail)}
              alt={product?.[forLocale({ ar: "name_alt" }, "name")]}
              height="100%"
              width="100%"
              objectFit="contain"
            />
          </CardActionArea>
        </Grid>
        <Grid item xs={7} sx={{ height: "100%" }}>
          <Stack height="100%" width="100%" direction="column">
            <Stack
              height="100%"
              direction="column"
              spacing={0.5}
              sx={{ px: 0.75, py: 1 }}
            >
              <Typography
                variant="h6"
                color="primary"
                sx={{
                  fontWeight: "bold",
                  display: "-webkit-box",
                  overflow: "hidden",
                  WebkitBoxOrient: "vertical",
                  WebkitLineClamp: 2,
                }}
              >
                {product?.[forLocale({ ar: "name_alt" }, "name")]}
              </Typography>

              {subtitle && (
                <Typography variant="subtitle1" color="secondary" noWrap>
                  {subtitle}
                </Typography>
              )}

              {isPriced && (
                <Breadcrumbs
                  separator={
                    <Typography
                      variant={forDevice("caption", "subtitle2")}
                      children={`*${quantity ?? getCartItemQty(productId)}`}
                    />
                  }
                  sx={{
                    "& ol": {
                      alignItems: "baseline",
                    },
                  }}
                >
                  <AppPriceText
                    price={product?.price}
                    priceVariant={forDevice(
                      isSubTotal ? "subtitle1" : "h5",
                      "h5"
                    )}
                    currency={!isSubTotal && t("currency")}
                    currencyVariant="subtitle2"
                    color={"primary"}
                  />
                  {isSubTotal && (
                    <AppPriceText
                      price={subTotal}
                      priceVariant={forDevice("subtitle2", "h5")}
                      currency={t("currency")}
                      currencyVariant={forDevice("caption", "subtitle2")}
                      color={"primary"}
                    />
                  )}
                </Breadcrumbs>
              )}
            </Stack>
            {isPriced && (
              <>
                <Stack
                  direction={"row"}
                  justifyContent={"end"}
                  alignItems={"center"}
                  width="100%"
                  spacing={1}
                  px={0.5}
                  py={0.5}
                >
                  {!inFav && !inCheckout && (
                    <AppProductFavBtn
                      productId={productId}
                      product={product}
                      full={false}
                      size={forDevice("small", "medium", "large")}
                    />
                  )}
                  <AppProductCartBtn
                    productId={productId}
                    product={product}
                    full={false}
                    size={forDevice("small", "medium", "large")}
                  />
                </Stack>
              </>
            )}
          </Stack>
        </Grid>
      </Grid>

      {isPriced && (inFav || inCart || inCheckout) && (
        <MyFloater top={2} start={2}>
          {inFav && !inCheckout && (
            <AppProductFavBtn
              productId={productId}
              product={product}
              full={false}
              size={"small"}
              remover={true}
            />
          )}
          {(inCart || inCheckout) && (
            <AppProductCartBtn
              productId={productId}
              product={product}
              full={false}
              size={"small"}
              remover={true}
            />
          )}
        </MyFloater>
      )}
    </Card>
  );
};
export default AppProductWideCard;
