import {
  TextField,
  Card,
  CardContent,
  Container,
  InputAdornment,
  Stack,
  Typography,
  Button,
  RadioGroup,
  FormControlLabel,
  Radio,
} from "@mui/material";
import { useTranslation } from "../../configs/translation";
import AppScaffold from "../../layouts/AppScaffold";
import { useBreakpoints, useWidth } from "../../configs/breakpoints";
import MyImage from "../../components/MyImage";
import LogoIcon from "../../assets/images/logoIcon.png";
import {
  EmailTwoTone,
  LoginTwoTone,
  PasswordTwoTone,
  PersonAddAltTwoTone,
  PhoneTwoTone,
} from "@mui/icons-material";
import { Link, useNavigate, useParams } from "react-router-dom";
import { eDom } from "../../models/core/my-js";
import { useMyClient } from "../../models/MyClient";
import { useLayoutEffect } from "react";
import { LoadingButton } from "@mui/lab";
import { useMyCart } from "../../models/MyCart";
import { useMyFav } from "../../models/MyFav";
import { State } from "../../models/core/my-react";

const LoginPage = () => {
  const { nav } = useParams();
  const { t } = useTranslation();
  const { forDevice } = useWidth();
  const { down } = useBreakpoints();
  const navigate = useNavigate();
  const mobile = down("tablet");
  const { isClient, loginCall, loginWaiting } = useMyClient();
  const { cart } = useMyCart();
  const { fav } = useMyFav();

  // check is client
  useLayoutEffect(() => {
    if (isClient) navigate(`/${nav ? nav : ""}`, { replace: true });
  }, [isClient, navigate, nav]);

  return (
    <AppScaffold main={false} header={t("login")}>
      <Container
        fixed={!mobile}
        maxWidth={mobile ? "desktop" : "tablet"}
        sx={{ my: forDevice(2, null, 4) }}
      >
        <form
          onSubmit={eDom.eventPreventDefault((event, target) => {
            let fd = new FormData(target);
            loginCall(fd.get("username"), fd.get("password"), cart, fav);
          })}
        >
          <MobileLogin mobile={mobile} loading={loginWaiting} />
          <DesktopLogin mobile={mobile} loading={loginWaiting} />
        </form>
      </Container>
    </AppScaffold>
  );
};
export default LoginPage;

const LoginLogin = ({ loading }) => {
  const { nav } = useParams();
  const { t } = useTranslation();

  const type = State("e");

  return (
    <>
      <RadioGroup
        row
        value={type.value}
        onChange={({ target: { value } }) => {
          type.value = value;
        }}
      >
        <FormControlLabel control={<Radio />} label={t("email")} value="e" />
        <FormControlLabel
          control={<Radio />}
          label={t("mobile_number")}
          value="p"
        />
      </RadioGroup>

      <TextField
        label={t(type.value === "p" ? "mobile_number" : "email")}
        size="normal"
        margin="normal"
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment
              position="start"
              children={
                type.value === "p" ? <PhoneTwoTone /> : <EmailTwoTone />
              }
            />
          ),
          sx: { py: 1 },
        }}
        name="username"
        type={type.value === "p" ? "tel" : "email"}
        required
        inputProps={type.value === "p" ? { minLength: 11, maxLength: 11 } : {}}
      />
      <TextField
        label={t("password")}
        size="normal"
        margin="normal"
        fullWidth
        InputProps={{
          startAdornment: (
            <InputAdornment position="start" children={<PasswordTwoTone />} />
          ),
          sx: { py: 1 },
        }}
        name="password"
        type="password"
        required
        inputProps={{ minLength: 6 }}
      />

      <LoadingButton
        loading={loading}
        loadingPosition="start"
        startIcon={<LoginTwoTone />}
        variant="contained"
        type="submit"
        children={t("login")}
        fullWidth
      />

      <Button
        component={Link}
        to={`/register${nav ? `/${nav}` : ""}`}
        replace={true}
        variant={"outlined"}
        color="primary"
        startIcon={<PersonAddAltTwoTone />}
        children={t("register_title")}
      />
    </>
  );
};

const MobileLogin = ({ mobile, loading }) => {
  const { t } = useTranslation();

  if (!mobile) {
    return null;
  } else {
    return (
      <Stack spacing={3} alignItems={"center"}>
        <MyImage
          src={LogoIcon}
          alt={t("welcome_greeting")}
          width={100}
          height={100}
          style={{ borderRadius: 4 }}
        />

        <LoginLogin loading={loading} />
      </Stack>
    );
  }
};

const DesktopLogin = ({ mobile, loading }) => {
  const { t } = useTranslation();

  if (mobile) {
    return null;
  } else {
    return (
      <Card variant={"outlined"}>
        <CardContent>
          <Stack spacing={3} alignItems={"center"}>
            <Typography variant="h3" children={t("login")} />

            <LoginLogin loading={loading} />
          </Stack>
        </CardContent>
      </Card>
    );
  }
};
