import { Button, Container, Stack } from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useWidth } from "../../configs/breakpoints";
import { useTranslation } from "../../configs/translation";
import {
  ArrowBackTwoTone,
  ArrowForwardTwoTone,
  LoginTwoTone,
  PersonAddAltTwoTone,
} from "@mui/icons-material";
import { Link, useNavigate } from "react-router-dom";

const AccessPage = () => {
  const { forDevice } = useWidth();
  const { t, forDir } = useTranslation();
  const navigate = useNavigate();

  return (
    <AppScaffold>
      <Container maxWidth={"desktop"} sx={{ my: forDevice(2, null, 4) }}>
        <Stack
          spacing={3}
          sx={{ px: { xs: 0, sm: 10, md: 20, lg: 40, xl: 60 }, py: 20 }}
        >
          <Button
            component={Link}
            to={"/login"}
            variant={"outlined"}
            color="secondary"
            startIcon={<LoginTwoTone />}
            children={t("login_title")}
          />

          <Button
            component={Link}
            to={"/register"}
            variant={"outlined"}
            color="secondary"
            startIcon={<PersonAddAltTwoTone />}
            children={t("register_title")}
          />

          <Button
            onClick={() => {
              navigate(window.history.length > 1 ? -1 : "/");
            }}
            variant="outlined"
            color="primary"
            startIcon={forDir(
              <ArrowBackTwoTone fontSize="small" />,
              <ArrowForwardTwoTone fontSize="small" />
            )}
          >
            {t("back")}
          </Button>
        </Stack>
      </Container>
    </AppScaffold>
  );
};
export default AccessPage;
