import { useEffect, useLayoutEffect } from "react";
import { ApiState } from "./MyApis";
import { useMyClient } from "./MyClient";
import { Context, Ref, SessionStorageState, State } from "./core/my-react";
import { eList } from "./core/my-js";

export const MyCartContext = Context(() => {
    const { CID, isClient } = useMyClient();
    const cart = SessionStorageState('cart', { fallback: {} });
    const render = State(0);
    const getCartApi = ApiState("public/ecommerce/clients/cart/get", { autoCall: false });
    const isFirstRun = Ref(true);

    // on client login and logout
    useLayoutEffect(() => {
        if (CID) {
            getCartApi.callApi({ CID: CID });
        } else if (!isFirstRun.value) {
            cart.value = {};
        }
        isFirstRun.value = false;
        // eslint-disable-next-line
    }, [CID]);

    // on get carts set in carts
    useEffect(() => {
        if (getCartApi.value?.cart && getCartApi.value?.cart?.length > 0) {
            for (let prod of getCartApi.value.cart) {
                cart.value[prod.id] = { product: prod, qty: prod.quantity }
            }
            render.value += 1;
            cart.save(cart.value);
        }
        // eslint-disable-next-line
    }, [getCartApi.value]);

    // manage cart
    const fromProduct = (product) => {
        return {
            min: parseInt(product?.min_order_quantity ?? 1),
            step: parseInt(product?.step_order_quantity ?? 1),
            max: parseInt(Math.min(product?.max_order_quantity ?? product?.stock ?? 0, product?.stock ?? 0)),
            stock: product?.stock,
            reserve: (!product?.stock || product?.stock === "0") && product?.per_order === "1"
        };
    }
    const manageItem = (productId, product, type) => {
        var { min, step, max, reserve } = fromProduct(product);
        let item = { ...cart.value[productId] ?? { product: product, qty: 0 } };
        item.qty = parseInt(item.qty ?? 0);
        if (type === 1) {
            item.qty += step;
            if (item.qty < min) {
                item.qty = min;
            }
            if (!reserve && item.qty > max) {
                item.qty = max;
            }
        } else if (type === -1) {
            item.qty -= step;
            if (!reserve && item.qty > max) {
                item.qty = max;
            }
            if (item.qty < min) {
                item.qty = 0;
            }
        } else {
            item.qty = 0;
        }
        return item;
    }
    const manageCart = (productId, product, type) => {
        let item = manageItem(productId, product, type);
        if (item.qty === 0) {
            delete cart.value[productId];
        } else {
            cart.value[productId] = item;
        }
        render.value += 1;
        cart.save(cart.value);
        // cart.value = { ...cart.value };
    }
    const setCart = (mngApi, productId, product, type) => {
        if (mngApi && isClient) {
            let item = manageItem(productId, product, type);
            mngApi.callApi({
                CID: CID,
                product_id: productId,
                quantity: item.qty,
            }, {
                onSuccess: () => {
                    manageCart(productId, product, type);
                }
            });
        } else {
            manageCart(productId, product, type);
        }
    }

    // api for components
    const manageApi = (productId, product) => {
        const api = ApiState("public/ecommerce/clients/cart/manage", {
            autoCall: false,
        });
        return {
            api: api,
            get waiting() { return api.waiting },
            addCartItem: () => addCartItem(productId, product, api),
            subCartItem: () => subCartItem(productId, product, api),
            delCartItem: () => delCartItem(productId, product, api),
        }
    }

    // do to cart
    const getCartItem = (productId) => {
        return cart.value?.[productId] ?? null;
    };
    const getCartItemQty = (productId) => {
        let item = cart.value?.[productId];
        if (item) {
            return parseInt(item.qty)
        } else {
            return null;
        }
    };
    const getCartItemValue = (productId) => {
        let item = cart.value?.[productId];
        if (item) {
            return parseInt(item.qty) * parseFloat(item.product.price);
        } else {
            return null;
        }
    };
    const addCartItem = (productId, product, mngApi) => {
        setCart(mngApi, productId, product, 1);
    };
    const subCartItem = (productId, product, mngApi) => {
        setCart(mngApi, productId, product, -1);
    };
    const delCartItem = (productId, product, mngApi) => {
        setCart(mngApi, productId, product, 0);
    }; const cartProducts = () => {
        return eList.toArray(cart.value, (sum, item) => item.product);
    }
    const cartCount = () => Object.values(cart.value).reduce((sum, item) => sum + parseInt(item.qty), 0);
    const cartValue = () => Object.values(cart.value).reduce((sum, item) => sum + (parseInt(item.qty) * parseFloat(item.product.price)), 0);
    const cartReset = () => {
        cart.value = {};
        getCartApi.callApi({ CID: CID });
    }

    return {
        get cart() { return cart.value },
        get cartProducts() { return cartProducts() },
        cartCount,
        cartValue,
        cartReset,
        getCartItem,
        getCartItemQty,
        getCartItemValue,
        addCartItem,
        subCartItem,
        delCartItem,
        manageApi
    };
});
export const useMyCart = MyCartContext.Use;
export const MyCartProvider = MyCartContext.Provider;
export const MyCartConsumer = MyCartContext.Consumer;
export const MyCartProvCons = MyCartContext.ProvCons;