import {
  Box,
  Button,
  Container,
  Divider,
  Skeleton,
  Stack,
  Typography,
} from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useBreakpoints, useWidth } from "../../configs/breakpoints";
import { eList } from "../../models/core/my-js";
import { useTranslation } from "../../configs/translation";
import { ArrowBackTwoTone, ArrowForwardTwoTone } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";
import { useMyClient } from "../../models/MyClient";
import { useLayoutEffect } from "react";
import AppOrderWideCard from "../../layouts/AppOrderWideCard";
import { ApiState } from "../../models/MyApis";
import useMyDialog from "../../components/MyDialog";

const OrdersPage = () => {
  const navigate = useNavigate();
  const { t, forDir } = useTranslation();
  const { forDevice } = useWidth();
  const { down } = useBreakpoints();
  const mobile = down("tablet");
  const { CID, isClient, orderCancelCall, orderCancelWaiting } = useMyClient();
  const ordersData = ApiState("public/ecommerce/clients/orders/get", {
    bodyData: {
      CID: CID,
    },
    autoCall: isClient,
  });
  const { createMyDialog, MyDialogAction } = useMyDialog();
  const { openDialog, closeDialog, dialogWidget } = createMyDialog({
    iconColor: "error",
    content: t("cancel_order_confirm"),
    actions: [
      MyDialogAction({
        onClick: () => {
          closeDialog();
        },
        text: t("yes"),
        color: "error",
      }),
      MyDialogAction({ close: true, text: t("no") }),
    ],
  });

  // out if cart empty
  useLayoutEffect(() => {
    if (!isClient) {
      navigate(window.history.length > 1 ? -1 : "/", { replace: true });
    }
    // eslint-disable-next-line
  }, [isClient]);

  return (
    <AppScaffold
      main={false}
      header={t("orders")}
      contentLoading={ordersData.waiting || orderCancelWaiting}
    >
      <Container
        fixed={!mobile}
        maxWidth={mobile ? "desktop" : "laptop"}
        sx={{ my: forDevice(2, null, 4) }}
      >
        {!mobile && (
          <Divider
            textAlign="left"
            sx={{ overflow: "auto", width: "100%", mb: 2 }}
          >
            <Typography color="primary" children={t("orders")} />
          </Divider>
        )}

        {ordersData.waiting && (
          <Skeleton variant="rectangular" width="100%" height={400} />
        )}

        {!ordersData.waiting && ordersData.value?.length === 0 && (
          <Box
            sx={{
              width: "100%",
              py: { mobile: 10, tablet: 30 },
              bgcolor: "background.light",
            }}
          >
            <Stack spacing={forDevice(2, null, 4)} alignItems={"center"}>
              <Typography
                variant="h5"
                textAlign="center"
                children={t("orders_empty")}
              />
              <Button
                variant="text"
                onClick={() => {
                  navigate(window.history.length > 1 ? -1 : "/");
                }}
                color="primary"
                startIcon={forDir(
                  <ArrowBackTwoTone fontSize="small" />,
                  <ArrowForwardTwoTone fontSize="small" />
                )}
              >
                {t("back")}
              </Button>
            </Stack>
          </Box>
        )}

        {!ordersData.waiting && ordersData.value?.length > 0 && (
          <Stack spacing={1}>
            {eList.toArray(ordersData.value, (index, item) => (
              <AppOrderWideCard
                key={`ol-${index}`}
                order={item}
                onCancel={() => {
                  openDialog({
                    content: t("cancel_order_confirm_id", {
                      fillers: [item?.id],
                    }),
                    actions: [
                      MyDialogAction({ close: true, text: t("no") }),
                      MyDialogAction({
                        onClick: () => {
                          closeDialog();
                          orderCancelCall(item.id, () => {
                            ordersData.recallApi();
                          });
                        },
                        text: t("yes"),
                        color: "error",
                      }),
                    ],
                  });
                }}
              />
            ))}
          </Stack>
        )}

        {dialogWidget}
      </Container>
    </AppScaffold>
  );
};
export default OrdersPage;
