import { useBreakpoints } from "../configs/breakpoints";
import { useTranslation } from "../configs/translation";
import {
  AppBar,
  Badge,
  Box,
  Button,
  Container,
  Fab,
  Stack,
  Toolbar,
  Typography,
  Grid,
  Divider,
  SwipeableDrawer,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
} from "@mui/material";
import MyImage from "../components/MyImage";
import LogoIcon from "../assets/images/logoIcon.png";
import {
  BeenhereTwoTone,
  CategoryTwoTone,
  EmailTwoTone,
  FavoriteTwoTone,
  GridViewTwoTone,
  HomeTwoTone,
  LanguageTwoTone,
  LocalShippingTwoTone,
  LoginTwoTone,
  LogoutTwoTone,
  PermIdentityTwoTone,
  PersonAddAltTwoTone,
  PhoneTwoTone,
  ShoppingCartTwoTone,
  StorefrontTwoTone,
} from "@mui/icons-material";
import { BsWhatsapp } from "react-icons/bs";
import { eList } from "../models/core/my-js";
import { useMyFav } from "../models/MyFav";
import { useMyCart } from "../models/MyCart";
import Logo from "../assets/images/logo.png";
import { State } from "../models/core/my-react";
import { Link } from "react-router-dom";
import { useMyClient } from "../models/MyClient";

const AppFooter = ({ main, mobileFooter, mobileFooterHeight = 75 }) => {
  const { down } = useBreakpoints();
  const mobile = down("tablet");

  return (
    <>
      <MainMobileFooter mobile={mobile} main={main} />
      <SubMobileFooter
        mobile={mobile}
        main={main}
        content={mobileFooter}
        height={mobileFooterHeight}
      />
      <DektopFooter mobile={mobile} main={main} />
    </>
  );
};
export default AppFooter;

const MainMobileFooter = ({ mobile, main }) => {
  const { t, locales, locale, setLocale } = useTranslation();
  const { isClient, logoutClient } = useMyClient();
  const { cartCount } = useMyCart();
  const { favCount } = useMyFav();
  const drawer = State(false);

  const curLoc = () => {
    var lk = Object.keys(locales);
    var l = lk.indexOf(locale);
    lk.splice(l, 1);
    return locales[lk[0]];
  };

  return (
    mobile &&
    main && (
      <>
        <Box height={75} />
        <AppBar
          position="fixed"
          variant="dense"
          color="white"
          sx={{ top: "auto", width: "100%", bottom: 0 }}
        >
          <Toolbar
            variant="dense"
            sx={{
              width: "100%",
              borderTopWidth: 1,
              borderTopStyle: "solid",
              borderTopColor: "light.main",
              px: 0.5,
              pt: 0.5,
            }}
            disableGutters
          >
            <Stack
              direction={"row"}
              spacing={0.5}
              sx={{
                width: "100%",
              }}
            >
              {eList.toArray(
                [
                  {
                    n: <Typography variant="caption" children={t("store")} />,
                    i: <StorefrontTwoTone />,
                    u: "/products",
                  },
                  {
                    n: <Typography variant="caption" children={t("cart")} />,
                    i: (
                      <Badge
                        badgeContent={cartCount()}
                        color="secondary"
                        children={<ShoppingCartTwoTone />}
                      />
                    ),
                    u: "/cart",
                  },
                  {
                    sx: {
                      position: "relative",
                    },
                    c: (
                      <Fab
                        component={Link}
                        to={"/"}
                        size="large"
                        color="white"
                        sx={{
                          position: "absolute",
                          top: -20,
                          left: 0,
                          right: 0,
                          mx: "auto",
                          overflow: "hidden",
                          padding: 0.5,
                        }}
                      >
                        <MyImage
                          src={LogoIcon}
                          alt={t("welcome_greeting")}
                          width={"100%"}
                          height={"100%"}
                          bgColor={"transparent"}
                          objectFit={"contain"}
                        />
                      </Fab>
                    ),
                  },
                  {
                    n: (
                      <Typography variant="caption" children={t("favorites")} />
                    ),
                    i: (
                      <Badge
                        badgeContent={favCount()}
                        color="secondary"
                        children={<FavoriteTwoTone />}
                      />
                    ),
                    u: "/favorites",
                  },
                  {
                    n: <Typography variant="caption" children={t("more")} />,
                    i: <GridViewTwoTone />,
                    o: () => (drawer.value = true),
                  },
                ],
                (index, item) => (
                  <Box
                    key={`mf-${index}`}
                    sx={{
                      ...(item.sx ?? {}),
                      flexGrow: 1,
                      flexShrink: 0,
                      flexBasis: 0,
                    }}
                  >
                    {!item.c && (
                      <Button
                        {...(item?.u
                          ? { component: Link, to: item?.u }
                          : { onClick: item?.o })}
                        size="large"
                        variant="text"
                        color="inherit"
                        disableElevation
                        fullWidth
                        sx={{ py: 1, px: 0.5 }}
                      >
                        <Stack
                          direction={"column"}
                          spacing={0.1}
                          alignItems={"center"}
                        >
                          {item.i}
                          <Typography noWrap>{item.n}</Typography>
                        </Stack>
                      </Button>
                    )}
                    {item.c}
                  </Box>
                )
              )}
            </Stack>
          </Toolbar>
        </AppBar>
        <SwipeableDrawer
          anchor={"right"}
          open={drawer.value}
          onOpen={() => (drawer.value = true)}
          onClose={() => (drawer.value = false)}
          ModalProps={{
            keepMounted: false,
          }}
        >
          <Stack
            spacing={1}
            direction="column"
            sx={{ width: 225, color: "primary" }}
            role="presentation"
          >
            <MyImage
              src={Logo}
              alt={t("welcome_greeting")}
              width={"100%"}
              height={70}
              imgWidth={"100%"}
              imgHeight={"100%"}
              sx={{ padding: 1 }}
              style={{ borderRadius: 4 }}
            />

            {eList.toArray(
              [
                {
                  n: t("home"),
                  i: <HomeTwoTone />,
                  u: "/",
                },
                {
                  n: t("store"),
                  i: <StorefrontTwoTone />,
                  u: "/products",
                },
                {
                  n: t("categories"),
                  i: <CategoryTwoTone />,
                  u: "/categories",
                },
                {
                  n: t("brands"),
                  i: <BeenhereTwoTone />,
                  u: "/brands",
                },
                null,
                ...(isClient
                  ? [
                      {
                        n: t("profile"),
                        i: <PermIdentityTwoTone />,
                        u: "/profile",
                      },
                      {
                        n: t("orders"),
                        i: <LocalShippingTwoTone />,
                        u: "/orders",
                      },
                      {
                        n: t("logout"),
                        i: <LogoutTwoTone />,
                        o: () => logoutClient(),
                        c: "error.main",
                      },
                    ]
                  : [
                      {
                        n: t("login"),
                        i: <LoginTwoTone />,
                        u: "/login",
                      },
                      {
                        n: t("register"),
                        i: <PersonAddAltTwoTone />,
                        u: "/register",
                      },
                    ]),
                null,
                {
                  n: curLoc().name,
                  i: <LanguageTwoTone />,
                  o: () => setLocale(curLoc().code),
                },
              ],
              (index, item) => {
                if (!item) {
                  return <Divider key={`fl-${index}`} />;
                } else {
                  return (
                    <ListItem
                      key={`fl-${index}`}
                      disablePadding
                      sx={{ color: item?.c ?? "inherit" }}
                    >
                      <ListItemButton
                        {...(item.u
                          ? { component: Link, to: item?.u }
                          : { onClick: item?.o })}
                      >
                        <ListItemIcon
                          sx={{ color: "inherit" }}
                          children={item.i}
                        />
                        <ListItemText
                          sx={{ color: "inherit" }}
                          primary={item.n}
                        />
                      </ListItemButton>
                    </ListItem>
                  );
                }
              }

              // <Link
              //   key={`fl-${index}`}
              //   to={item.u}
              //   style={{
              //     display: "contents",
              //     textDecoration: "none",
              //     color: "inherit",
              //   }}
              // >
              //   <Button
              //     size="large"
              //     variant="text"
              //     color="inherit"
              //     disableElevation
              //     startIcon={item.i}
              //   >
              //     {item.n}
              //   </Button>
              // </Link>
            )}
          </Stack>
        </SwipeableDrawer>
      </>
    )
  );
};
const SubMobileFooter = ({ mobile, main, content, height = 75 }) => {
  return (
    mobile &&
    !main &&
    content && (
      <>
        <Box height={height} />
        <AppBar
          position="fixed"
          variant="dense"
          color="white"
          sx={{ top: "auto", width: "100%", bottom: 0 }}
        >
          <Toolbar
            variant="dense"
            sx={{
              width: "100%",
              borderTopWidth: 1,
              borderTopStyle: "solid",
              borderTopColor: "light.main",
              px: 0.5,
              pt: 0.5,
            }}
            disableGutters
          >
            {content}
          </Toolbar>
        </AppBar>
      </>
    )
  );
};
const DektopFooter = ({ mobile, main }) => {
  const { t } = useTranslation();

  return (
    !mobile && (
      <>
        <AppBar position="static" variant="dense" color="light" sx={{}}>
          <Container maxWidth={"desktop"}>
            <Toolbar
              variant="dense"
              sx={{
                width: "100%",
                py: 5,
              }}
            >
              <Grid container columnSpacing={1}>
                <Grid item xs={8}>
                  <Stack
                    direction={"column"}
                    justifyContent={"space-around"}
                    alignItems={"start"}
                    spacing={1}
                    sx={{
                      width: "100%",
                    }}
                  >
                    <MyImage
                      src={Logo}
                      alt={t("welcome_greeting")}
                      width={300}
                      imgWidth={"100%"}
                      height={"auto"}
                      style={{ borderRadius: 4 }}
                    />

                    <Typography
                      variant={"subtitle1"}
                      children={t("company_desc")}
                      sx={{ textIndent: 50 }}
                    />
                  </Stack>
                </Grid>
                <Grid item xs={4}>
                  <Stack
                    direction={"column"}
                    justifyContent={"space-around"}
                    alignItems={"start"}
                    spacing={0.5}
                    sx={{
                      width: "100%",
                    }}
                  >
                    <Divider sx={{ width: "100%" }}>
                      <Typography
                        variant={"subtitle1"}
                        children={t("contact_us")}
                      />
                    </Divider>
                    {eList.toArray(
                      [
                        // {
                        //   i: <MapTwoTone />,
                        //   n: "149 ahmed lashin - taksem omar ebn el khatab - gesr el suez Cairo, Cairo Governorate, Egypt 11775",
                        //   l: "https://maps.app.goo.gl/eDqRuazBnXXV1Rch7",
                        // },
                        {
                          i: <EmailTwoTone />,
                          n: "sales@istkibal-egypt.com",
                          l: "mailto: ",
                          cn: "enFonts",
                        },
                        {
                          i: <BsWhatsapp />,
                          n: "WhatsApp",
                          l: "https://api.whatsapp.com/send?phone=",
                        },
                        {
                          i: <PhoneTwoTone />,
                          n: (
                            <Typography
                              variant="span"
                              className="ltr"
                              children={"2 0100 180 9603"}
                            />
                          ),
                          l: "tel:201001809603",
                          cn: "enFonts",
                        },
                        // {
                        //   i: <PhoneTwoTone />,
                        //   n: "2 0122 172 2221",
                        //   l: "tel:201221722221",
                        // },
                      ],
                      (index, item) => (
                        <Button
                          key={`fcl-${index}`}
                          className={item?.cn}
                          variant="text"
                          startIcon={item.i}
                          children={item.n}
                          href={item.l}
                          target="_blank"
                          sx={item?.sx}
                        />
                      )
                    )}
                  </Stack>
                </Grid>
              </Grid>
            </Toolbar>
          </Container>
        </AppBar>
        <AppBar position="static" variant="dense" color="white" sx={{}}>
          <Container maxWidth={"desktop"}>
            <Toolbar
              variant="dense"
              sx={{
                width: "100%",
                py: 0.5,
                px: 3,
                minHeight: "unset",
              }}
            >
              <Stack
                direction={"row"}
                justifyContent={"space-between"}
                alignItems={"start"}
                spacing={0.5}
                sx={{
                  width: "100%",
                }}
              >
                <Typography className="ltr enFonts" textAlign={"center"}>
                  {"Copyright Istikbal Egypt 2024"}
                </Typography>

                <Link
                  href="https://exabytellc.com"
                  target="_blank"
                  underline="hover"
                >
                  <Typography className="ltr enFonts" textAlign={"center"}>
                    {"Powered By Exabyte LLC"}
                  </Typography>
                </Link>
              </Stack>
            </Toolbar>
          </Container>
        </AppBar>
      </>
    )
  );
};
