import { MyGrid, MyGridItem } from "../components/MyGrid";
import { useWidth } from "../configs/breakpoints";
import { cardHeight } from "../configs/params";
import { eList } from "../models/core/my-js";
import AppProductCard from "./AppProductCard";

const AppProductCardGrid = ({ products, inFav, inCart, inCheckout }) => {
  const { forDevice } = useWidth();
  const ch = cardHeight(forDevice);

  return (
    <MyGrid
      cols={{ xs: 2, sm: 3, md: 4, lg: 5, xl: 6 }}
      rowHeight={ch}
      spacing={1}
      width={"100%"}
    >
      {eList.toArray(products, (index, item) => {
        return (
          <MyGridItem key={`ps-${index}`}>
            <AppProductCard
              productId={item.id}
              product={item}
              inFav={inFav}
              inCart={inCart}
              inCheckout={inCheckout}
            />
          </MyGridItem>
        );
      })}
    </MyGrid>
  );
};
export default AppProductCardGrid;
