import {
  Box,
  Card,
  CardActionArea,
  Container,
  Divider,
  Skeleton,
  Stack,
  Typography,
} from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useWidth } from "../../configs/breakpoints";
import { useTranslation } from "../../configs/translation";
import { useMyHome } from "../../models/MyHome";
import { eList } from "../../models/core/my-js";
import { ApisEB } from "../../configs/apis";
import { MyGrid, MyGridItem } from "../../components/MyGrid";
import MyImage from "../../components/MyImage";
import { Link } from "react-router-dom";

const CategoriesPage = () => {
  const { forDevice } = useWidth();
  const homeApi = useMyHome();

  return (
    <AppScaffold>
      <Container maxWidth={"desktop"} sx={{ my: forDevice(2, null, 4) }}>
        <CategoriesCategories categories={homeApi.data?.categories} />
      </Container>
    </AppScaffold>
  );
};
export default CategoriesPage;

const CategoriesCategories = ({ categories }) => {
  const { t } = useTranslation();
  const { forDevice } = useWidth();

  if (!categories) {
    return <Skeleton variant="rounded" height={500} />;
  } else if (categories?.length > 0) {
    return (
      <Stack direction="column" spacing={forDevice(2, 4)} width={"100%"}>
        <Divider textAlign="left" sx={{ overflow: "auto", width: "100%" }}>
          <Typography color="primary" children={t("categories")} />
        </Divider>

        <MyGrid
          cols={{ xs: 3, sm: 4, md: 6, lg: 9, xl: 10 }}
          cross={"stretch"}
          mainItem={"stretch"}
          crossItem={"stretch"}
          spacing={1}
          width={"100%"}
        >
          {eList.toArray(categories, (index, category) => {
            return (
              <MyGridItem key={`mcg-${index}`}>
                <CategoriesCard category={category} />
              </MyGridItem>
            );
          })}
        </MyGrid>
      </Stack>
    );
  } else {
    return null;
  }
};

const CategoriesCard = ({ category }) => {
  const { forLocale } = useTranslation();

  return (
    <Card
      variant={"outlined"}
      sx={{
        position: "relative",
        width: "100%",
        height: "100%",
        bgcolor: "background.white",
        borderColor: "light.main",
      }}
      square
    >
      <CardActionArea
        sx={{
          flexGrow: 1,
          width: "100%",
          height: "100%",
        }}
      >
        <Link
          style={{
            flexGrow: 1,
            width: "100%",
            height: "100%",
            textDecoration: "none",
          }}
          to={`/products/p/1/c/${category?.id}`}
        >
          <Stack height="100%" direction="column">
            <MyImage
              src={ApisEB.getMedia(category?.thumbnail)}
              alt={category?.[forLocale({ ar: "name_alt" }, "name")]}
              height={100}
              width="100%"
              objectFit="contain"
            />
            <Box sx={{ px: 0.25, py: 0.5 }}>
              <Typography
                variant="body2"
                color="primary"
                textAlign={"center"}
                sx={{
                  display: "-webkit-box",
                  overflow: "hidden",
                  WebkitBoxOrient: "vertical",
                  WebkitLineClamp: 2,
                }}
              >
                {category?.[forLocale({ ar: "name_alt" }, "name")]}
              </Typography>
            </Box>
          </Stack>
        </Link>
      </CardActionArea>
    </Card>
  );
};
