import { createTheme, responsiveFontSizes } from "@mui/material";
import { useTranslation } from "./translation";
import { eList, eColor } from "../models/core/my-js";
import { primaryColor, primaryTextColor, secondColor } from "./params";

export function DefaultTheme() {
    const { fontfamily, dir } = useTranslation();
    const colors = {
        primary: eColor.parse(primaryColor),
        secondary: eColor.parse(secondColor),
        white: eColor.colors.white,
        light: eColor.parse("#eee"),
        dark: eColor.parse("#333"),
        black: eColor.colors.black,
        error: eColor.colors.red,
        warning: eColor.colors.orangered,
        alert: eColor.colors.teal,
        info: eColor.parse("#0066cc"),
        success: eColor.colors.green,
    };
    const subColors = [{
        n: "",
        m: (c) => c,
        c: (c) => c.getTextColor(),
    }, {
        n: "t",
        m: (c) => c.fadeOut(0.5),
        c: (c) => c.getTextColor(),
    }, {
        n: "2",
        m: (c) => c.setBrightness(0.8),
        c: (c) => c.darken(0.6),
    }, {
        n: "2t",
        m: (c) => c.setBrightness(0.8).fadeOut(0.5),
        c: (c) => c.darken(0.6),
    }, {
        n: "3",
        m: (c) => c.setBrightness(0.2),
        c: (c) => c.lighten(0.6),
    }, {
        n: "3t",
        m: (c) => c.setBrightness(0.2).fadeOut(0.5),
        c: (c) => c.lighten(0.6),
    }, {
        n: "4",
        m: (c) => c.setBrightness(0.7),
        c: (c) => c.lighten(0.6),
    }, {
        n: "4t",
        m: (c) => c.setBrightness(0.7).fadeOut(0.5),
        c: (c) => c.darken(0.6),
    }, {
        n: "5",
        m: (c) => c.setBrightness(0.9),
        c: (c) => c.lighten(0.6),
    }, {
        n: "5t",
        m: (c) => c.setBrightness(0.9).fadeOut(0.5),
        c: (c) => c.darken(0.6),
    }];

    var material = createTheme({
        direction: dir,
        palette: {
            mode: "light",
            ...eList.toObject(colors, (k, v, obj) => {
                let c = eColor.parse(v);
                return eList.toObject(subColors, (i, v2) => {
                    let cc = v2.m(c);
                    let ct = v2.c(cc);
                    return {
                        [k + v2.n]: {
                            main: cc.getRGBA,
                            dark: cc.darken(0.25).getRGBA,
                            light: cc.lighten(0.25).getRGBA,
                            contrastText: ct.getRGBA,
                        }
                    }
                });
            }),
            text: {
                primary: eColor.parse(primaryTextColor).getRGBA,
            },
            background: {
                default: "#eee",
                paper: "#fff",

                ...eList.toObject(colors, (k, v, obj) => {
                    let c = eColor.parse(v);
                    return eList.toObject(subColors, (i, v2) => {
                        return {
                            [k + v2.n]: v2.m(c).getRGBA
                        }
                    });
                }),
            },
        },
        typography: {
            fontFamily: fontfamily,
            fontSize: 10,
            htmlFontSize: 13,
        },
        breakpoints: {
            values: {
                xs: 0,
                sm: 576,
                md: 768,
                lg: 992,
                xl: 1200,
                xx: 1440,

                mobile: 0,
                tablet: 640,
                laptop: 1024,
                desktop: 1440,
            },
        },
        components: {
            MuiButton: {
                styleOverrides: {
                    root: {
                        minWidth: "unset",// unset minwidth of buttons
                    },
                },
            },
        },
    });

    material = responsiveFontSizes(material, {
        breakpoints: ['xs', 'sm', 'md', 'lg', 'xl', 'xx'],
        factor: 5
    });

    return { material: material };
}