import {
  Breadcrumbs,
  Divider,
  Skeleton,
  Stack,
  Typography,
  Link,
} from "@mui/material";
import { useTranslation } from "../../../configs/translation";
import { ApisEB } from "../../../configs/apis";
import MyTabSlider, {
  MyTabSliderIcon,
  MyTabSliderImage,
  MyTabSliderLabel,
} from "../../../components/MyTabSlider";
import { useWidth } from "../../../configs/breakpoints";
import { eList } from "../../../models/core/my-js";
import { useRef } from "react";
import { CategoryTwoTone } from "@mui/icons-material";

const ProductsCategories = ({
  categoryId,
  onChange,
  categories,
  brandId,
  brands,
}) => {
  const { t, forLocale } = useTranslation();
  const { forDevice } = useWidth();
  const slidRef = useRef(null);

  const s = forDevice(36, 42, 48);

  // get lists
  const getData = () => {
    var fbrand = brands?.find((obj) => obj?.id === brandId?.value);
    var categories2 = categories;
    if (fbrand) {
      categories2 = categories2.filter((obj) =>
        fbrand?.categories.includes(obj?.id)
      );
    }

    function getCParents(cid, cats, arr = []) {
      var cat = cats?.find((obj) => obj?.id === cid);
      if (cat) {
        getCParents(cat?.parent_id, cats, arr);
        arr.push(cat);
      }
      return arr;
    }

    var cat = categories2?.find((obj) => obj?.id === categoryId?.value);
    var catChilds = eList.arrCountIf(
      categories2,
      (i, obj) => obj?.parent_id === categoryId?.value
    );

    var pcat = categories2?.find(
      (obj) => obj?.id === (catChilds > 0 ? cat?.id : cat?.parent_id)
    );

    var tsCats = categories2?.filter((obj) => {
      if (catChilds > 0) {
        return obj?.parent_id === categoryId?.value;
      } else {
        return obj?.parent_id === cat?.parent_id;
      }
    });

    var v = 0;
    var i = tsCats?.findIndex((obj) => obj?.id === categoryId?.value);
    if (i > -1) v = i + 1;

    var bc = [
      {
        id: null,
        name: t("categories"),
        name_alt: t("categories"),
      },
      ...getCParents(cat?.id, categories2, []),
    ];
    var ts = [
      {
        id: cat?.parent_id ?? null,
        name: t("all") + forDevice("", (pcat && ` - ${pcat?.name}`) ?? ""),
        name_alt:
          t("all") + forDevice("", (pcat && ` - ${pcat?.name_alt}`) ?? ""),
        icon: (
          <CategoryTwoTone
            color="primary"
            fontSize={forDevice("small", null, "medium")}
          />
        ),
      },
      ...(tsCats ?? []),
    ];

    return {
      v: v,
      k: pcat?.id ?? null,
      bc: bc,
      ts: ts,
      arr: categories2,
    };
  };
  var lists = getData();

  if (!lists.arr) {
    return <Skeleton variant="rounded" height={100} />;
  } else if (lists.arr?.length > 0) {
    return (
      <Stack direction="column" spacing={forDevice(0, 1)} width={"100%"}>
        <Divider textAlign="left" sx={{ overflow: "auto", width: "100%" }}>
          <Breadcrumbs
            maxItems={forDevice(1, 2, 5)}
            separator="›"
            sx={{ maxWidth: "100%", width: "max-content" }}
          >
            {eList.toArray(lists.bc, (index, item) => {
              if (item?.id !== categoryId.value) {
                return (
                  <Link
                    key={`${categoryId.value}cbc-${index}`}
                    underline="hover"
                    color="primary"
                    onClick={() => {
                      categoryId.value = item?.id;
                      if (slidRef?.current) {
                        slidRef.current.setValue(0);
                      }
                      onChange(item?.id);
                    }}
                    sx={{ cursor: "pointer" }}
                    children={item?.[forLocale({ ar: "name_alt" }, "name")]}
                  />
                );
              } else {
                return (
                  <Typography
                    key={`${categoryId.value}cbc-${index}`}
                    color="primary"
                    children={item?.[forLocale({ ar: "name_alt" }, "name")]}
                  />
                );
              }
            })}
          </Breadcrumbs>
        </Divider>
        <MyTabSlider
          ref={slidRef}
          value={lists.v}
          key={`mcs-${lists.k}`}
          data={lists.ts}
          scrollButtons={forDevice(false, null, "auto")}
          customKey={(item) => item?.id}
          onChange={(index, item) => onChange(item?.id)}
          iconPosition="start"
          sx={(selected) => {
            return {
              borderColor: selected ? "primary.main" : "light.main",
              bgcolor: "background.light",
            };
          }}
          label={(item, selected) =>
            MyTabSliderLabel({
              variant: "body2",
              text: item?.[forLocale({ ar: "name_alt" }, "name")],
              maxLines: null,
              px: 1,
              color: selected ? "primary.main" : "primary.main",
            })
          }
          icon={(item, selected) =>
            item.icon
              ? MyTabSliderIcon({
                  icon: item.icon,
                  width: s,
                  height: s,
                })
              : MyTabSliderImage({
                  src: ApisEB.getMedia(item?.thumbnail),
                  alt: item?.[forLocale({ ar: "name_alt" }, "name")],
                  width: s,
                  height: s,
                  objectFit: "contain",
                })
          }
        />
      </Stack>
    );
  } else {
    return null;
  }
};
export default ProductsCategories;
