import "react-multi-carousel/lib/styles.css";
import Carousel from "react-multi-carousel";
import { useTranslation } from "../configs/translation";
import { eList } from "../models/core/my-js";
import { IconButton } from "@mui/material";
import {
  ChevronLeftTwoTone,
  ChevronRightTwoTone,
  Circle,
  CircleTwoTone,
} from "@mui/icons-material";

const MyCarousel = ({
  items,
  itemRender,
  autoPlay = false,
  autoPlaySpeed = 10000,
  showDots = true,
  infinite = true,
  arrows = true,
  renderDotsOutside = true,
  dotsRender,
  leftArrowRender,
  rightArrowRender,
}) => {
  const { dir } = useTranslation();

  const CustomLeftArrow = ({ onClick, ...rest }) => {
    if (leftArrowRender) return leftArrowRender({ onClick });
    return (
      <IconButton onClick={() => onClick()} color="secondary">
        <ChevronLeftTwoTone />
      </IconButton>
    );
  };
  const CustomRightArrow = ({ onClick, ...rest }) => {
    if (rightArrowRender) return rightArrowRender({ onClick });
    return (
      <IconButton onClick={() => onClick()} color="secondary">
        <ChevronRightTwoTone />
      </IconButton>
    );
  };
  const CustomDot = ({ onClick, ...rest }) => {
    const { index, active } = rest;
    const item = items[index];
    if (dotsRender) return dotsRender({ index, item, active, onClick });
    return (
      <IconButton
        onClick={() => onClick()}
        color={active ? "secondary" : "dark"}
        size="small"
      >
        {active ? (
          <Circle fontSize={"small"} />
        ) : (
          <CircleTwoTone fontSize={"small"} />
        )}
      </IconButton>
    );
  };

  return (
    <>
      <style>{".outside-dots { position: static; }"}</style>
      <Carousel
        swipeable={true}
        showDots={showDots}
        infinite={infinite}
        autoPlay={autoPlay}
        autoPlaySpeed={autoPlaySpeed}
        keyBoardControl={false}
        arrows={arrows}
        responsive={{
          all: {
            breakpoint: { max: 999999, min: 0 },
            items: 1,
          },
        }}
        direction={dir}
        rtl={dir === "rtl"}
        customLeftArrow={<CustomLeftArrow />}
        customRightArrow={<CustomRightArrow />}
        customDot={<CustomDot />}
        renderDotsOutside={renderDotsOutside}
        dotListClass="outside-dots"
      >
        {eList.generateArray(items?.length, (i) => {
          return itemRender({ index: i, item: items[i] });
        })}
      </Carousel>
    </>
  );
};
export default MyCarousel;
