import { useLayoutEffect } from "react";
import {
  Box,
  Stack,
  Container,
  Typography,
  Divider,
  Skeleton,
} from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useNavigate, useParams } from "react-router-dom";
import { useTranslation } from "../../configs/translation";
import { useBreakpoints, useWidth } from "../../configs/breakpoints";
import { ApiState } from "../../models/MyApis";
import { useMyClient } from "../../models/MyClient";
import AppProductWideCard from "../../layouts/AppProductWideCard";
import { eDate, eList } from "../../models/core/my-js";
import { FaListCheck } from "react-icons/fa6";
import { BsCartXFill } from "react-icons/bs";
import { FaTruckFast } from "react-icons/fa6";
import { PinDrop } from "@mui/icons-material";
import { FaBox } from "react-icons/fa6";
import { MdAssignmentReturn } from "react-icons/md";
import AppPriceText from "../../layouts/AppPriceText";

const OrderPage = () => {
  // navigation
  const navigate = useNavigate();
  const { t, forDir } = useTranslation();
  const { orderId } = useParams();
  const { forDevice } = useWidth();
  const { down } = useBreakpoints();
  const mobile = down("tablet");
  const { CID, isClient } = useMyClient();

  // out if cart empty
  useLayoutEffect(() => {
    if (!isClient) {
      navigate(window.history.length > 1 ? -1 : "/", { replace: true });
    }
    // eslint-disable-next-line
  }, [isClient]);

  const orderData = ApiState("public/ecommerce/clients/orders/details", {
    bodyData: {
      CID: CID,
      order_id: orderId,
    },
  });

  const statusIcon = (() => {
    switch (orderData.value?.order?.status) {
      case "processing":
        return <FaListCheck style={{ width: 20, height: 20 }} />;
      case "canceled":
        return <BsCartXFill style={{ width: 20, height: 20 }} />;
      case "shipping":
        return <FaTruckFast style={{ width: 20, height: 20 }} />;
      case "arrived":
        return <PinDrop sx={{ width: 20, height: 20 }} />;
      case "delivered":
        return <FaBox style={{ width: 20, height: 20 }} />;
      case "returned":
        return <MdAssignmentReturn style={{ width: 20, height: 20 }} />;
      default:
        return null;
    }
  })();
  const statusColor = (() => {
    switch (orderData.value?.order?.status) {
      case "processing":
        return "info.main";
      case "canceled":
        return "error.main";
      case "shipping":
        return "info.main";
      case "arrived":
        return "info.main";
      case "delivered":
        return "success.main";
      case "returned":
        return "error.main";
      default:
        return null;
    }
  })();
  const statusBgColor = (() => {
    switch (orderData.value?.order?.status) {
      case "processing":
        return "info5t.light";
      case "canceled":
        return "error5t.light";
      case "shipping":
        return "info5t.light";
      case "arrived":
        return "info5t.light";
      case "delivered":
        return "success5t.light";
      case "returned":
        return "error5t.light";
      default:
        return null;
    }
  })();

  // return
  return (
    <AppScaffold
      header={`${t("order_no")}: ${orderId}`}
      main={false}
      contentLoading={orderData.waiting}
    >
      <Container
        fixed={!mobile}
        maxWidth={mobile ? "desktop" : "laptop"}
        sx={{ my: forDevice(2, null, 4) }}
      >
        {!mobile && (
          <Divider
            textAlign="left"
            sx={{ overflow: "auto", width: "100%", mb: 2 }}
          >
            <Typography color="primary" children={`${t("order_no")}: ${orderId}`} />
          </Divider>
        )}

        <Stack spacing={forDevice(2, null, 4)}>
          {orderData.waiting && (
            <Skeleton variant="rectangular" width="100%" height={250} />
          )}

          {!orderData.waiting && (
            <>
              <Typography
                variant="h6"
                color={statusColor}
                sx={{
                  fontWeight: "bold",
                }}
              >
                <Stack
                  direction="row"
                  gap={2}
                  alignItems={"center"}
                  width={"max-content"}
                >
                  <Box
                    sx={{
                      display: "inline-flex",
                      width: 40,
                      height: 40,
                      borderRadius: 2,
                      bgcolor: statusBgColor,
                      justifyContent: "center",
                      alignItems: "center",
                    }}
                  >
                    {statusIcon}
                  </Box>
                  <Stack
                    direction="column"
                    alignItems={"start"}
                    width={"max-content"}
                  >
                    {t(orderData.value?.order?.status)}

                    <Typography
                      className="ltr enFonts"
                      variant="caption"
                      component="span"
                      color="primary"
                      sx={{ textAlign: forDir("start", "end") }}
                    >
                      {
                        new eDate(orderData.value?.order?.addstamp)
                          .readableDatetimeFormat
                      }
                    </Typography>
                  </Stack>
                </Stack>
              </Typography>
              <Stack direction="column" spacing={0.5} sx={{ px: 1 }}>
                <Box>
                  <Typography variant="subtitle2" component="span">
                    {t("order_no") + ":"}
                  </Typography>
                  <Typography
                    variant="h6"
                    component="span"
                    sx={{ fontWeight: "bold", px: 1 }}
                  >
                    {orderData.value?.order?.id}
                  </Typography>
                </Box>

                <Box>
                  <Typography variant="subtitle2" component="span">
                    {t("address") + ":"}
                  </Typography>
                  <Typography
                    variant="h6"
                    component="span"
                    sx={{ fontWeight: "bold", px: 1 }}
                  >
                    {orderData.value?.order?.address_name}
                  </Typography>
                </Box>

                <AppPriceText
                  color={"primary"}
                  price={orderData.value?.order?.total_amount}
                  currency={t("currency")}
                />
              </Stack>
            </>
          )}

          <Divider />

          {orderData.waiting && (
            <Skeleton variant="rectangular" width="100%" height={250} />
          )}
          {!orderData.waiting && (
            <Stack spacing={1}>
              {eList.toArray(orderData.value.products, (index, item) => (
                <AppProductWideCard
                  key={`opl-${index}`}
                  productId={item.id}
                  product={item}
                  quantity={item.quantity}
                />
              ))}
            </Stack>
          )}
        </Stack>
      </Container>
    </AppScaffold>
  );
};
export default OrderPage;
