import { Typography } from "@mui/material";
import { eNum } from "../models/core/my-js";

const AppPriceText = ({
  price,
  priceVariant = "h5",
  currency,
  currencyVariant = "subtitle2",
  color = "inherit",
  sx,
}) => {
  return (
    <Typography component="span" color={color} sx={sx}>
      <Typography
        variant={priceVariant}
        component="span"
        color="inherit"
        sx={{ fontWeight: "bold" }}
      >
        {eNum.readable(parseFloat(price), 0)}
      </Typography>
      <Typography
        variant={currencyVariant}
        component="span"
        color="inherit"
        sx={{ px: 0.25 }}
      >
        {currency}
      </Typography>
    </Typography>
  );
};
export default AppPriceText;
