import { useEffect } from "react";
import { Box, Stack, Grid, Container } from "@mui/material";
import AppScaffold from "../../layouts/AppScaffold";
import { useNavigate, useParams } from "react-router-dom";
import { useTranslation } from "../../configs/translation";
import ProductImages from "./layouts/ProductImages";
import ProductTitle from "./layouts/ProductTitle";
import ProductDesc from "./layouts/ProductDesc";
import ProductSimilar from "./layouts/ProductSimilar";
import { useWidth } from "../../configs/breakpoints";
import { ApiStoredState } from "../../models/MyApis";

const ProductPage = () => {
  // navigation
  const navigate = useNavigate();
  const { t, forLocale } = useTranslation();
  const { productId } = useParams();
  const { forDevice, forSize } = useWidth();

  const productData = ApiStoredState("public/ecommerce/products/details", {
    bodyData: {
      product_id: productId,
    },
  });

  const variantsData = ApiStoredState("public/ecommerce/products/variants", {
    bodyData: {
      product_id: productId,
    },
  });

  const fthresh = forSize(2, 3, 4, 5, 6) * 4;
  const similarData = ApiStoredState("public/ecommerce/products/similar", {
    bodyData: {
      thresh: fthresh,
      product_id: productId,
    },
  });

  // get product & similar from api, reset scroll
  useEffect(() => {
    // no product, go home
    if (!productId) {
      navigate("/");
    }

    // reset scroll
    window.scrollTo(0, 0);

    // recall for new page
    productData.callApi({
      product_id: productId,
    });
    variantsData.callApi({
      product_id: productId,
    });
    similarData.callApi({
      thresh: fthresh,
      product_id: productId,
    });

    // eslint-disable-next-line
  }, [productId]);

  // return
  return (
    <AppScaffold
      title={
        productData.value === null
          ? t("product")
          : productData.value?.product?.[forLocale({ ar: "name_alt" }, "name")]
      }
      main={false}
    >
      <Container maxWidth={"desktop"} sx={{ my: forDevice(2, null, 4) }}>
        <Stack spacing={forDevice(2, null, 4)}>
          <Box>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <ProductImages
                  key={`pdi-${productId}`}
                  productId={productId}
                  product={productData.value?.product}
                  media={productData.value?.media}
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <ProductTitle
                  key={`pdt-${productId}`}
                  productId={productId}
                  product={productData.value?.product}
                  variants={variantsData.value}
                />
              </Grid>
            </Grid>
          </Box>
          <ProductDesc
            key={`pdd-${productId}`}
            productId={productId}
            product={productData.value?.product}
          />
          <ProductSimilar
            key={`pds-${productId}`}
            productId={productId}
            products={similarData.value?.products}
          />
        </Stack>
      </Container>
    </AppScaffold>
  );
};
export default ProductPage;
