import {
  Breadcrumbs,
  Divider,
  Skeleton,
  Stack,
  Typography,
  Link,
} from "@mui/material";
import { useTranslation } from "../../../configs/translation";
import { ApisEB } from "../../../configs/apis";
import MyTabSlider, {
  MyTabSliderIcon,
  MyTabSliderImage,
  MyTabSliderLabel,
} from "../../../components/MyTabSlider";
import { useWidth } from "../../../configs/breakpoints";
import { eList } from "../../../models/core/my-js";
import { useRef } from "react";
import { BeenhereTwoTone } from "@mui/icons-material";

const ProductsBrands = ({
  brandId,
  onChange,
  brands,
  categoryId,
  categories,
}) => {
  const { t, forLocale } = useTranslation();
  const { forDevice } = useWidth();
  const slidRef = useRef(null);

  const sw = forDevice(72, 76, 82);
  const sh = forDevice(26, 32, 38);

  // get lists
  const getData = () => {
    var fcat = categories?.find((obj) => obj?.id === categoryId?.value);
    var brands2 = brands;
    if (fcat) {
      brands2 = brands2?.filter((obj) => fcat?.brands.includes(obj?.id));
    }

    var bcarr = brands2?.find((obj) => obj?.id === brandId?.value);
    var v = 0;
    var i = brands2?.findIndex((obj) => obj?.id === brandId?.value);
    if (i > -1) v = i + 1;

    var bc = [
      {
        id: null,
        name: t("brands"),
        name_alt: t("brands"),
      },
      ...(bcarr ? [bcarr] : []),
    ];
    var ts = [
      {
        id: null,
        name: t("all"),
        name_alt: t("all"),
        icon: (
          <BeenhereTwoTone
            color="primary"
            fontSize={forDevice("small", null, "medium")}
          />
        ),
      },
      ...(brands2 ?? []),
    ];

    return {
      v: v,
      k: `brands-${v}`,
      bc: bc,
      ts: ts,
      arr: brands2,
    };
  };
  var lists = getData();

  if (!lists.arr) {
    return <Skeleton variant="rounded" height={90} />;
  } else if (lists.arr?.length > 0) {
    return (
      <Stack direction="column" spacing={forDevice(0, 1)} width={"100%"}>
        <Divider textAlign="left" sx={{ overflow: "auto", width: "100%" }}>
          <Breadcrumbs
            maxItems={forDevice(1, 2, 5)}
            separator="›"
            sx={{ maxWidth: "100%", width: "max-content" }}
          >
            {eList.toArray(lists.bc, (index, item) => {
              if (item?.id !== brandId.value) {
                return (
                  <Link
                    key={`${brandId.value}cbc-${index}`}
                    underline="hover"
                    color="primary"
                    onClick={() => {
                      brandId.value = item?.id;
                      if (slidRef?.current) {
                        slidRef.current.setValue(0);
                      }
                      onChange(item?.id);
                    }}
                    sx={{ cursor: "pointer" }}
                    children={item?.[forLocale({ ar: "name_alt" }, "name")]}
                  />
                );
              } else {
                return (
                  <Typography
                    key={`${brandId.value}cbc-${index}`}
                    color="primary"
                    children={item?.[forLocale({ ar: "name_alt" }, "name")]}
                  />
                );
              }
            })}
          </Breadcrumbs>
        </Divider>
        <MyTabSlider
          ref={slidRef}
          value={lists.v}
          key={`mbs-${lists.k}`}
          data={lists.ts}
          scrollButtons={forDevice(false, null, "auto")}
          customKey={(item) => item?.id}
          onChange={(index, item) => onChange(item?.id)}
          iconPosition="start"
          sx={(selected) => {
            return {
              borderColor: selected ? "primary.main" : "light.main",
              bgcolor: "background.light",
            };
          }}
          label={(item, selected) =>
            MyTabSliderLabel({
              variant: "body2",
              text: item?.[forLocale({ ar: "name_alt" }, "name")],
              maxLines: null,
              px: 1,
              color: selected ? "primary.main" : "primary.main",
            })
          }
          icon={(item, selected) =>
            item.icon
              ? MyTabSliderIcon({
                  icon: item.icon,
                  width: sw,
                  height: sh,
                })
              : MyTabSliderImage({
                  src: ApisEB.getMedia(item?.thumbnail),
                  alt: item?.[forLocale({ ar: "name_alt" }, "name")],
                  width: sw,
                  height: sh,
                  objectFit: "contain",
                })
          }
        />
      </Stack>
    );
  } else {
    return null;
  }
};
export default ProductsBrands;
