// packages
import React, { createContext, useContext, useEffect, useRef, useState } from "react";
import { eCookie, eLocaleStorage, eSessionStorage } from "./my-js";
//==============================< State
export const State = (initValue) => {
  const [getV, setV] = useState(initValue);
  return {
    get value() {
      return getV;
    },
    set value(value) {
      setV(value);
      return value;
    },
  };
};
//==============================< Ref
export const Ref = (initValue) => {
  const get = useRef(initValue);
  return {
    get value() {
      return get.current;
    },
    set value(value) {
      get.current = value;
      return get.current;
    },
  };
};
//==============================< session storage State
export function SessionStorageState(name, { fallback = null } = []) {
  const key = `ss:${name}`;
  const [getV, setV] = useState(() => eSessionStorage.get(key) ?? fallback);

  useEffect(() => {
    save(getV)
    // eslint-disable-next-line
  }, [getV]);

  const save = (value) => {
    if (value) {
      eSessionStorage.set(key, value);
    } else {
      eSessionStorage.del(key);
    }
  }

  return {
    get value() {
      return getV;
    },
    set value(value) {
      setV(value);
      return value;
    },
    save
  };
}
