//==============================< cookie State
export function CookieState(name, { fallback = null, expireHours = 24 * 7 } = []) {
  const key = `c:${name}`;
  const [getV, setV] = useState(() => eCookie.get(key) ?? fallback);

  useEffect(() => {
    save(getV);
    // eslint-disable-next-line
  }, [getV]);

  const save = (value) => {
    if (value) {
      eCookie.set(key, value, { expireHours: expireHours });
    } else {
      eCookie.del(key);
    }
  }

  return {
    get value() {
      return getV;
    },
    set value(value) {
      setV(value);
      return value;
    },
    save
  };
}
//==============================< cookie State
export function AsyncState(func = async () => null) {
  const [getW, setW] = useState(false);
  const [getV, setV] = useState(null);

  const run = async (params) => {
    setW(true);
    setV(null);
    return await new Promise((resolve) => {
      setTimeout(async () => {
        try {
          let r = await func(params);
          resolve(r);
          setV(r);
          setW(false);
        } catch (e) {
          resolve(null);
          setW(false)
        }
      }, 10);
    });
  }

  return {
    get value() {
      return getV;
    },
    get waiting() {
      return getW;
    },
    run: run,
  };
}
//==============================< stateRef
export const RefState = (initValue) => {
  const state = State(initValue);
  const ref = Ref(initValue);

  return {
    state,
    ref,
    get value() {
      return ref.value;
    },
    set value(value) {
      ref.value = value;
      state.value = value;
      return ref.value;

    }
  };
}
//==============================< Context
export const Context = (func = () => { }) => {
  const Context = createContext({});

  return {
    Context: Context,
    Use: () => {
      const ctx = useContext(Context);

      if (!ctx) {
        throw new Error('context must be used within a MyProvider');
      }

      return ctx;
    },
    Provider: (p) => {
      return <Context.Provider value={func()} children={p.children} />;
    },
    Consumer: (child = (obj) => { }) => {
      return <Context.Consumer children={child} />;
    },
    ProvCons: (child = (obj) => { }) => {
      return <Context.Provider value={func()} children={<Context.Consumer children={child} />} />;
    },
  };
};
//==============================< Translation
export function createTranslationContext(translation) {
  return Context(() => {
    const locale = State(translation.locale.code);
    const dir = State(translation.locale.dir);
    const fonts = State(translation.locale.fonts);
    const locales = State(translation.locales);

    const setLocale = (newLocale) => {
      translation.setLocale(newLocale, { reloadPage: false });
      locale.value = translation.locale.code;
      dir.value = translation.locale.dir;
      fonts.value = translation.locale.fonts;
      locales.value = translation.locales;
    };

    const forLocale = (options, fallback) => {
      if (options?.[locale.value]) {
        return options?.[locale.value];
      }
      return fallback;
    };

    const forDir = (ltr, rtl) => {
      return (dir.value === "rtl" ? rtl : ltr);
    };

    return {
      locale: locale.value,
      dir: dir.value,
      fonts: fonts.value,
      fontfamily: fonts.value?.join(","),
      locales: locales.value,
      setLocale,
      forLocale,
      forDir,
      t: translation.translate.bind(translation),
    };
  });
}