//
import React from "react";
import {
  Typography,
  Card,
  Stack,
  CardActionArea,
  Box,
  Button,
} from "@mui/material";
import { useTranslation } from "../configs/translation";
import { FaListCheck } from "react-icons/fa6";
import { BsCartXFill } from "react-icons/bs";
import { FaTruckFast } from "react-icons/fa6";
import { PinDrop } from "@mui/icons-material";
import { FaBox } from "react-icons/fa6";
import { MdAssignmentReturn } from "react-icons/md";
import AppPriceText from "./AppPriceText";
import { eDate } from "../models/core/my-js";
import { Link } from "react-router-dom";
import MyFloater from "../components/MyFloater";

//
const AppOrderWideCard = ({ order, onCancel }) => {
  const { t, forDir } = useTranslation();

  const statusIcon = (() => {
    switch (order.status) {
      case "processing":
        return <FaListCheck style={{ width: 20, height: 20 }} />;
      case "canceled":
        return <BsCartXFill style={{ width: 20, height: 20 }} />;
      case "shipping":
        return <FaTruckFast style={{ width: 20, height: 20 }} />;
      case "arrived":
        return <PinDrop sx={{ width: 20, height: 20 }} />;
      case "delivered":
        return <FaBox style={{ width: 20, height: 20 }} />;
      case "returned":
        return <MdAssignmentReturn style={{ width: 20, height: 20 }} />;
      default:
        return null;
    }
  })();
  const statusColor = (() => {
    switch (order.status) {
      case "processing":
        return "info.main";
      case "canceled":
        return "error.main";
      case "shipping":
        return "info.main";
      case "arrived":
        return "info.main";
      case "delivered":
        return "success.main";
      case "returned":
        return "error.main";
      default:
        return null;
    }
  })();
  const statusBgColor = (() => {
    switch (order.status) {
      case "processing":
        return "info5t.light";
      case "canceled":
        return "error5t.light";
      case "shipping":
        return "info5t.light";
      case "arrived":
        return "info5t.light";
      case "delivered":
        return "success5t.light";
      case "returned":
        return "error5t.light";
      default:
        return null;
    }
  })();
  return (
    <Card
      variant={"outlined"}
      sx={{
        position: "relative",
        width: "100%",
        height: "auto",
        bgcolor: "background.white",
        borderColor: "light.main",
        borderRadius: 1,
      }}
      square
    >
      <CardActionArea component={Link} to={`/order/${order?.id}`}>
        <Stack direction="column" spacing={1} sx={{ px: 0.75, py: 1 }}>
          <Typography
            variant="h6"
            color={statusColor}
            sx={{
              fontWeight: "bold",
            }}
          >
            <Stack
              direction="row"
              gap={2}
              alignItems={"center"}
              width={"max-content"}
            >
              <Box
                sx={{
                  display: "inline-flex",
                  width: 40,
                  height: 40,
                  borderRadius: 2,
                  bgcolor: statusBgColor,
                  justifyContent: "center",
                  alignItems: "center",
                }}
              >
                {statusIcon}
              </Box>
              <Stack
                direction="column"
                alignItems={"start"}
                width={"max-content"}
              >
                {t(order?.status)}

                <Typography
                  className="ltr enFonts"
                  variant="caption"
                  component="span"
                  color="primary"
                  sx={{ textAlign: forDir("start", "end") }}
                >
                  {new eDate(order?.addstamp).readableDatetimeFormat}
                </Typography>
              </Stack>
            </Stack>
          </Typography>
          <Stack direction="column" spacing={0.5} sx={{ px: 1 }}>
            <Box>
              <Typography variant="subtitle2" component="span">
                {t("order_no") + ":"}
              </Typography>
              <Typography
                variant="h6"
                component="span"
                sx={{ fontWeight: "bold", px: 1 }}
              >
                {order?.id}
              </Typography>
            </Box>

            <Box>
              <Typography variant="subtitle2" component="span">
                {t("address") + ":"}
              </Typography>
              <Typography
                variant="h6"
                component="span"
                sx={{ fontWeight: "bold", px: 1 }}
              >
                {order?.address_name}
              </Typography>
            </Box>

            <AppPriceText
              color={"secondary"}
              price={order?.total_amount}
              currency={t("currency")}
            />
          </Stack>
        </Stack>
      </CardActionArea>

      {order?.status === "processing" && (
        <MyFloater bottom={4} end={4}>
          <Button
            onClick={onCancel}
            variant="outlined"
            color="error"
            startIcon={<BsCartXFill />}
          >
            {t("cancel")}
          </Button>
        </MyFloater>
      )}
    </Card>
  );
};
export default AppOrderWideCard;
