import {
  AddTwoTone,
  AddShoppingCartTwoTone,
  RemoveTwoTone,
  ShoppingCartTwoTone,
  RemoveCircle,
} from "@mui/icons-material";
import { Button, ButtonGroup, Typography } from "@mui/material";
import { useMyCart } from "../models/MyCart";
import { useTranslation } from "../configs/translation";
import { LoadingButton } from "@mui/lab";
import MyIcons, { MySubIcon } from "../components/MyIcons";

const AppProductCartBtn = ({
  sx,
  productId,
  product,
  full = true,
  size = "medium",
  mobile = false,
  fullWidth = false,
  remover = false,
}) => {
  const { t } = useTranslation();
  const { getCartItem, manageApi } = useMyCart();
  const manage = manageApi(productId, product);

  const isOutStock = !product?.stock || product?.stock === "0";
  const isReservable = isOutStock && product?.per_order === "1";

  const item = getCartItem(productId);

  if (remover) {
    return (
      <LoadingButton
        loading={manage.waiting}
        onClick={() => {
          manage.delCartItem();
        }}
        color="error"
        size={size}
        sx={{ px: 1, py: 1 }}
      >
        <MyIcons
          baseIcon={
            <ShoppingCartTwoTone
              color={manage.waiting ? "transparent" : "secondary"}
            />
          }
        >
          <MySubIcon
            icon={
              <RemoveCircle
                color={manage.waiting ? "transparent" : "error2"}
                fontSize={"small"}
              />
            }
            h={4}
            v={4}
          />
        </MyIcons>
      </LoadingButton>
    );
  } else {
    if (item) {
      const btns = [
        <Button
          key={`csub`}
          variant="outlined"
          onClick={() => {
            manage.subCartItem();
          }}
          size={size}
          disabled={manage.waiting}
        >
          <RemoveTwoTone color="warning" fontSize="small" />
        </Button>,
        <Button
          key={`cnum`}
          disableFocusRipple
          disableRipple
          size={size}
          sx={{ py: 0 }}
          disabled={manage.waiting}
        >
          <Typography className="enFonts" variant="subtitle1">
            {item.qty}
          </Typography>
        </Button>,
        <Button
          key={`cadd`}
          variant="outlined"
          onClick={() => {
            manage.addCartItem();
          }}
          size={size}
          disabled={manage.waiting}
        >
          <AddTwoTone color="success" fontSize="small" />
        </Button>,
      ];

      if (full) {
        return (
          <ButtonGroup
            variant="outlined"
            size={size}
            fullWidth={fullWidth}
            sx={sx}
          >
            <Button
              color="secondary"
              variant="contained"
              disableFocusRipple
              disableRipple
              disableElevation
              size={size}
              disabled={manage.waiting}
            >
              <ShoppingCartTwoTone fontSize="small" />
            </Button>
            {btns}
          </ButtonGroup>
        );
      } else {
        return (
          <ButtonGroup
            variant="outlined"
            size={size}
            fullWidth={fullWidth}
            sx={sx}
          >
            {btns}
          </ButtonGroup>
        );
      }
    } else {
      return (
        <LoadingButton
          color="secondary"
          loading={manage.waiting}
          loadingPosition={"start"}
          onClick={() => {
            manage.addCartItem();
          }}
          variant="contained"
          startIcon={<AddShoppingCartTwoTone fontSize={size} />}
          size={size}
          fullWidth={fullWidth}
          disableElevation
          sx={{
            px: mobile ? 0.5 : 1.5,
            ...(sx ?? {}),
          }}
        >
          <Typography variant={mobile ? "caption" : "button"} noWrap>
            {isReservable ? t("reserve_in_cart") : t("add_to_cart")}
          </Typography>
        </LoadingButton>
      );
    }
  }
};
export default AppProductCartBtn;
