import {
  Box,
  Skeleton,
} from "@mui/material";
import { useTranslation } from "../../../configs/translation";
import { ApisEB } from "../../../configs/apis";
import { useWidth } from "../../../configs/breakpoints";
import MyCarousel from "../../../components/MyCarousel";
import MyImage from "../../../components/MyImage";

const HomeDeals = ({ deals }) => {
  const { forLocale } = useTranslation();
  const { forDevice } = useWidth();

  if (!deals) {
    return (
      <Skeleton
        variant="rounded"
        height={forDevice("25vh", "40vh", "60vh", "75vh")}
      />
    );
  } else if (deals?.length > 0) {
    return (
      <MyCarousel
        items={deals}
        itemRender={({ index, item }) => {
          return (
            <Box
              key={`cd-${index}`}
              sx={{
                height: forDevice("25vh", "40vh", "60vh", "75vh"),
              }}
            >
              <MyImage
                src={ApisEB.getMedia(item?.thumbnail)}
                alt={item?.[forLocale({ ar: "name_alt" }, "name")]}
                width={"100%"}
                height={"100%"}
                objectFit={"cover"}
              />
            </Box>
          );
        }}
      />
    );
  } else {
    return null;
  }
};
export default HomeDeals;
